INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(3, 'Ima', 'Leviticus', 1, 1, 'The LORD summoned Moses and spoke to him from the tent of meeting, saying:', 'en', 'NRSV-CE', 'The Burnt Offering'),
(3, 'Ima', 'Leviticus', 1, 2, 'Speak to the people of Israel and say to them: When any of you bring an offering of livestock to the LORD, you shall bring your offering from the herd or from the flock.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 1, 3, 'If the offering is a burnt offering from the herd, you shall offer a male without blemish; you shall bring it to the entrance of the tent of meeting, for acceptance in your behalf before the LORD.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 1, 4, 'You shall lay your hand on the head of the burnt offering, and it shall be acceptable in your behalf as atonement for you.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 1, 5, 'The bull shall be slaughtered before the LORD; and Aaron"s sons the priests shall offer the blood, dashing the blood against all sides of the altar that is at the entrance of the tent of meeting.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 1, 6, 'The burnt offering shall be flayed and cut up into its parts.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 1, 7, 'The sons of the priest Aaron shall put fire on the altar and arrange wood on the fire.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 1, 8, 'Aaron"s sons the priests shall arrange the parts, with the head and the suet, on the wood that is on the fire on the altar;', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 1, 9, 'but its entrails and its legs shall be washed with water. Then the priest shall turn the whole into smoke on the altar as a burnt offering, an offering by fire of pleasing odor to the LORD.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 1, 10, 'If your gift for a burnt offering is from the flock, from the sheep or goats, your offering shall be a male without blemish.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 1, 11, 'It shall be slaughtered on the north side of the altar before the LORD, and Aaron"s sons the priests shall dash its blood against all sides of the altar.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 1, 12, 'It shall be cut up into its parts, with its head and its suet, and the priest shall arrange them on the wood that is on the fire on the altar;', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 1, 13, 'but the entrails and the legs shall be washed with water. Then the priest shall offer the whole and turn it into smoke on the altar; it is a burnt offering, an offering by fire of pleasing odor to the LORD.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 1, 14, 'If your offering to the LORD is a burnt offering of birds, you shall choose your offering from turtledoves or pigeons.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 1, 15, 'The priest shall bring it to the altar and wring off its head, and turn it into smoke on the altar; and its blood shall be drained out against the side of the altar.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 1, 16, 'He shall remove its crop with its contents and throw it at the east side of the altar, in the place for ashes.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 1, 17, 'He shall tear it open by its wings without severing it. Then the priest shall turn it into smoke on the altar, on the wood that is on the fire; it is a burnt offering, an offering by fire of pleasing odor to the LORD.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(3, 'Ima', 'Leviticus', 2, 1, 'When anyone presents a grain offering to the LORD, the offering shall be of choice flour; the worshiper shall pour oil on it, and put frankincense on it,', 'en', 'NRSV-CE', 'Grain Offerings'),
(3, 'Ima', 'Leviticus', 2, 2, 'and bring it to Aaron"s sons the priests. After taking from it a handful of the choice flour and oil, with all its frankincense, the priest shall turn this token portion into smoke on the altar, an offering by fire of pleasing odor to the LORD.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 2, 3, 'And what is left of the grain offering shall be for Aaron and his sons, a most holy part of the offerings by fire to the LORD.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 2, 4, 'When you present a grain offering baked in the oven, it shall be of choice flour: unleavened cakes mixed with oil, or unleavened wafers spread with oil.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 2, 5, 'If your offering is grain prepared on a griddle, it shall be of choice flour mixed with oil, unleavened;', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 2, 6, 'break it in pieces, and pour oil on it; it is a grain offering.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 2, 7, 'If your offering is grain prepared in a pan, it shall be made of choice flour in oil.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 2, 8, 'You shall bring to the LORD the grain offering that is prepared in any of these ways; and when it is presented to the priest, he shall take it to the altar.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 2, 9, 'The priest shall remove from the grain offering its token portion and turn this into smoke on the altar, an offering by fire of pleasing odor to the LORD.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 2, 10, 'And what is left of the grain offering shall be for Aaron and his sons; it is a most holy part of the offerings by fire to the LORD.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 2, 11, 'No grain offering that you bring to the LORD shall be made with leaven, for you must not turn any leaven or honey into smoke as an offering by fire to the LORD.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 2, 12, 'You may bring them to the LORD as an offering of choice products, but they shall not be offered on the altar for a pleasing odor.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 2, 13, 'You shall not omit from your grain offerings the salt of the covenant with your God; with all your offerings you shall offer salt.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 2, 14, 'If you bring a grain offering of first fruits to the LORD, you shall bring as the grain offering of your first fruits coarse new grain from fresh ears, parched with fire.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 2, 15, 'You shall add oil to it and lay frankincense on it; it is a grain offering.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 2, 16, 'And the priest shall turn a token portion of it into smoke--some of the coarse grain and oil with all its frankincense; it is an offering by fire to the LORD.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(3, 'Ima', 'Leviticus', 3, 1, 'If the offering is a sacrifice of well-being, if you offer an animal of the herd, whether male or female, you shall offer one without blemish before the LORD.', 'en', 'NRSV-CE', 'Offerings of Well-Being'),
(3, 'Ima', 'Leviticus', 3, 2, 'You shall lay your hand on the head of the offering and slaughter it at the entrance of the tent of meeting; and Aaron"s sons the priests shall dash the blood against all sides of the altar.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 3, 3, 'You shall offer from the sacrifice of well-being, as an offering by fire to the LORD, the fat that covers the entrails and all the fat that is around the entrails;', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 3, 4, 'the two kidneys with the fat that is on them at the loins, and the appendage of the liver, which he shall remove with the kidneys.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 3, 5, 'Then Aaron"s sons shall turn these into smoke on the altar, with the burnt offering that is on the wood on the fire, as an offering by fire of pleasing odor to the LORD.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 3, 6, 'If your offering for a sacrifice of well-being to the LORD is from the flock, male or female, you shall offer one without blemish.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 3, 7, 'If you present a sheep as your offering, you shall bring it before the LORD', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 3, 8, 'and lay your hand on the head of the offering. It shall be slaughtered before the tent of meeting, and Aaron"s sons shall dash its blood against all sides of the altar.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 3, 9, 'You shall present its fat from the sacrifice of well-being, as an offering by fire to the LORD: the whole broad tail, which shall be removed close to the backbone, the fat that covers the entrails, and all the fat that is around the entrails;', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 3, 10, 'the two kidneys with the fat that is on them at the loins, and the appendage of the liver, which you shall remove with the kidneys.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 3, 11, 'Then the priest shall turn these into smoke on the altar as a food offering by fire to the LORD.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 3, 12, 'If your offering is a goat, you shall bring it before the LORD', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 3, 13, 'and lay your hand on its head; it shall be slaughtered before the tent of meeting; and the sons of Aaron shall dash its blood against all sides of the altar.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 3, 14, 'You shall present as your offering from it, as an offering by fire to the LORD, the fat that covers the entrails, and all the fat that is around the entrails;', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 3, 15, 'the two kidneys with the fat that is on them at the loins, and the appendage of the liver, which you shall remove with the kidneys.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 3, 16, 'Then the priest shall turn these into smoke on the altar as a food offering by fire for a pleasing odor.
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(3, 'Ima', 'Leviticus', 4, 1, 'The LORD spoke to Moses, saying,', 'en', 'NRSV-CE', 'Sin Offerings'),
(3, 'Ima', 'Leviticus', 4, 2, 'Speak to the people of Israel, saying: When anyone sins unintentionally in any of the LORD"s commandments about things not to be done, and does any one of them:', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 4, 3, 'If it is the anointed priest who sins, thus bringing guilt on the people, he shall offer for the sin that he has committed a bull of the herd without blemish as a sin offering to the LORD.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 4, 4, 'He shall bring the bull to the entrance of the tent of meeting before the LORD and lay his hand on the head of the bull; the bull shall be slaughtered before the LORD.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 4, 5, 'The anointed priest shall take some of the blood of the bull and bring it into the tent of meeting.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 4, 6, 'The priest shall dip his finger in the blood and sprinkle some of the blood seven times before the LORD in front of the curtain of the sanctuary.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 4, 7, 'The priest shall put some of the blood on the horns of the altar of fragrant incense that is in the tent of meeting before the LORD; and the rest of the blood of the bull he shall pour out at the base of the altar of burnt offering, which is at the entrance of the tent of meeting.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 4, 8, 'He shall remove all the fat from the bull of sin offering: the fat that covers the entrails and all the fat that is around the entrails;', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 4, 9, 'the two kidneys with the fat that is on them at the loins; and the appendage of the liver, which he shall remove with the kidneys,', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 4, 10, 'just as these are removed from the ox of the sacrifice of well-being. The priest shall turn them into smoke upon the altar of burnt offering.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 4, 11, 'But the skin of the bull and all its flesh, as well as its head, its legs, its entrails, and its dung--', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 4, 12, 'all the rest of the bull--he shall carry out to a clean place outside the camp, to the ash heap, and shall burn it on a wood fire; at the ash heap it shall be burned.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 4, 13, 'If the whole congregation of Israel errs unintentionally and the matter escapes the notice of the assembly, and they do any one of the things that by the LORD"s commandments ought not to be done and incur guilt;', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 4, 14, 'when the sin that they have committed becomes known, the assembly shall offer a bull of the herd for a sin offering and bring it before the tent of meeting.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 4, 15, 'The elders of the congregation shall lay their hands on the head of the bull before the LORD, and the bull shall be slaughtered before the LORD.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 4, 16, 'The anointed priest shall bring some of the blood of the bull into the tent of meeting,', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 4, 17, 'and the priest shall dip his finger in the blood and sprinkle it seven times before the LORD, in front of the curtain.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 4, 18, 'He shall put some of the blood on the horns of the altar that is before the LORD in the tent of meeting; and the rest of the blood he shall pour out at the base of the altar of burnt offering that is at the entrance of the tent of meeting.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 4, 19, 'He shall remove all its fat and turn it into smoke on the altar.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 4, 20, 'He shall do with the bull just as is done with the bull of sin offering; he shall do the same with this. The priest shall make atonement for them, and they shall be forgiven.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 4, 21, 'He shall carry the bull outside the camp, and burn it as he burned the first bull; it is the sin offering for the assembly.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 4, 22, 'When a ruler sins, doing unintentionally any one of all the things that by commandments of the LORD his God ought not to be done and incurs guilt,', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 4, 23, 'once the sin that he has committed is made known to him, he shall bring as his offering a male goat without blemish.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 4, 24, 'He shall lay his hand on the head of the goat; it shall be slaughtered at the spot where the burnt offering is slaughtered before the LORD; it is a sin offering.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 4, 25, 'The priest shall take some of the blood of the sin offering with his finger and put it on the horns of the altar of burnt offering, and pour out the rest of its blood at the base of the altar of burnt offering.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 4, 26, 'All its fat he shall turn into smoke on the altar, like the fat of the sacrifice of well-being. Thus the priest shall make atonement on his behalf for his sin, and he shall be forgiven.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 4, 27, 'If anyone of the ordinary people among you sins unintentionally in doing any one of the things that by the LORD"s commandments ought not to be done and incurs guilt,', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 4, 28, 'when the sin that you have committed is made known to you, you shall bring a female goat without blemish as your offering, for the sin that you have committed.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 4, 29, 'You shall lay your hand on the head of the sin offering; and the sin offering shall be slaughtered at the place of the burnt offering.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 4, 30, 'The priest shall take some of its blood with his finger and put it on the horns of the altar of burnt offering, and he shall pour out the rest of its blood at the base of the altar.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 4, 31, 'He shall remove all its fat, as the fat is removed from the offering of well-being, and the priest shall turn it into smoke on the altar for a pleasing odor to the LORD. Thus the priest shall make atonement on your behalf, and you shall be forgiven.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 4, 32, 'If the offering you bring as a sin offering is a sheep, you shall bring a female without blemish.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 4, 33, 'You shall lay your hand on the head of the sin offering; and it shall be slaughtered as a sin offering at the spot where the burnt offering is slaughtered.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 4, 34, 'The priest shall take some of the blood of the sin offering with his finger and put it on the horns of the altar of burnt offering, and pour out the rest of its blood at the base of the altar.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 4, 35, 'You shall remove all its fat, as the fat of the sheep is removed from the sacrifice of well-being, and the priest shall turn it into smoke on the altar, with the offerings by fire to the LORD. Thus the priest shall make atonement on your behalf for the sin that you have committed, and you shall be forgiven.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(3, 'Ima', 'Leviticus', 5, 1, 'When any of you sin in that you have heard a public adjuration to testify and--though able to testify as one who has seen or learned of the matter--do not speak up, you are subject to punishment.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 5, 2, 'Or when any of you touch any unclean thing--whether the carcass of an unclean beast or the carcass of unclean livestock or the carcass of an unclean swarming thing--and are unaware of it, you have become unclean, and are guilty.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 5, 3, 'Or when you touch human uncleanness--any uncleanness by which one can become unclean--and are unaware of it, when you come to know it, you shall be guilty.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 5, 4, 'Or when any of you utter aloud a rash oath for a bad or a good purpose, whatever people utter in an oath, and are unaware of it, when you come to know it, you shall in any of these be guilty.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 5, 5, 'When you realize your guilt in any of these, you shall confess the sin that you have committed.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 5, 6, 'And you shall bring to the LORD, as your penalty for the sin that you have committed, a female from the flock, a sheep or a goat, as a sin offering; and the priest shall make atonement on your behalf for your sin.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 5, 7, 'But if you cannot afford a sheep, you shall bring to the LORD, as your penalty for the sin that you have committed, two turtledoves or two pigeons, one for a sin offering and the other for a burnt offering.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 5, 8, 'You shall bring them to the priest, who shall offer first the one for the sin offering, wringing its head at the nape without severing it.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 5, 9, 'He shall sprinkle some of the blood of the sin offering on the side of the altar, while the rest of the blood shall be drained out at the base of the altar; it is a sin offering.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 5, 10, 'And the second he shall offer for a burnt offering according to the regulation. Thus the priest shall make atonement on your behalf for the sin that you have committed, and you shall be forgiven.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 5, 11, 'But if you cannot afford two turtledoves or two pigeons, you shall bring as your offering for the sin that you have committed one-tenth of an ephah of choice flour for a sin offering; you shall not put oil on it or lay frankincense on it, for it is a sin offering.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 5, 12, 'You shall bring it to the priest, and the priest shall scoop up a handful of it as its memorial portion, and turn this into smoke on the altar, with the offerings by fire to the LORD; it is a sin offering.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 5, 13, 'Thus the priest shall make atonement on your behalf for whichever of these sins you have committed, and you shall be forgiven. Like the grain offering, the rest shall be for the priest.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 5, 14, 'The LORD spoke to Moses, saying:', 'en', 'NRSV-CE', 'Offerings with Restitution'),
(3, 'Ima', 'Leviticus', 5, 15, 'When any of you commit a trespass and sin unintentionally in any of the holy things of the LORD, you shall bring, as your guilt offering to the LORD, a ram without blemish from the flock, convertible into silver by the sanctuary shekel; it is a guilt offering.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 5, 16, 'And you shall make restitution for the holy thing in which you were remiss, and shall add one-fifth to it and give it to the priest. The priest shall make atonement on your behalf with the ram of the guilt offering, and you shall be forgiven.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 5, 17, 'If any of you sin without knowing it, doing any of the things that by the LORD"s commandments ought not to be done, you have incurred guilt, and are subject to punishment.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 5, 18, 'You shall bring to the priest a ram without blemish from the flock, or the equivalent, as a guilt offering; and the priest shall make atonement on your behalf for the error that you committed unintentionally, and you shall be forgiven.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 5, 19, 'It is a guilt offering; you have incurred guilt before the LORD.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(3, 'Ima', 'Leviticus', 6, 1, 'The LORD spoke to Moses, saying:', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 6, 2, 'When any of you sin and commit a trespass against the LORD by deceiving a neighbor in a matter of a deposit or a pledge, or by robbery, or if you have defrauded a neighbor,', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 6, 3, 'or have found something lost and lied about it--if you swear falsely regarding any of the various things that one may do and sin thereby--', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 6, 4, 'when you have sinned and realize your guilt, and would restore what you took by robbery or by fraud or the deposit that was committed to you, or the lost thing that you found,', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 6, 5, 'or anything else about which you have sworn falsely, you shall repay the principal amount and shall add one-fifth to it. You shall pay it to its owner when you realize your guilt.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 6, 6, 'And you shall bring to the priest, as your guilt offering to the LORD, a ram without blemish from the flock, or its equivalent, for a guilt offering.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 6, 7, 'The priest shall make atonement on your behalf before the LORD, and you shall be forgiven for any of the things that one may do and incur guilt thereby.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 6, 8, 'The LORD spoke to Moses, saying:', 'en', 'NRSV-CE', 'Instructions concerning Sacrifices'),
(3, 'Ima', 'Leviticus', 6, 9, 'Command Aaron and his sons, saying: This is the ritual of the burnt offering. The burnt offering itself shall remain on the hearth upon the altar all night until the morning, while the fire on the altar shall be kept burning.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 6, 10, 'The priest shall put on his linen vestments after putting on his linen undergarments next to his body; and he shall take up the ashes to which the fire has reduced the burnt offering on the altar, and place them beside the altar.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 6, 11, 'Then he shall take off his vestments and put on other garments, and carry the ashes out to a clean place outside the camp.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 6, 12, 'The fire on the altar shall be kept burning; it shall not go out. Every morning the priest shall add wood to it, lay out the burnt offering on it, and turn into smoke the fat pieces of the offerings of well-being.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 6, 13, 'A perpetual fire shall be kept burning on the altar; it shall not go out.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 6, 14, 'This is the ritual of the grain offering: The sons of Aaron shall offer it before the LORD, in front of the altar.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 6, 15, 'They shall take from it a handful of the choice flour and oil of the grain offering, with all the frankincense that is on the offering, and they shall turn its memorial portion into smoke on the altar as a pleasing odor to the LORD.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 6, 16, 'Aaron and his sons shall eat what is left of it; it shall be eaten as unleavened cakes in a holy place; in the court of the tent of meeting they shall eat it.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 6, 17, 'It shall not be baked with leaven. I have given it as their portion of my offerings by fire; it is most holy, like the sin offering and the guilt offering.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 6, 18, 'Every male among the descendants of Aaron shall eat of it, as their perpetual due throughout your generations, from the LORD"s offerings by fire; anything that touches them shall become holy.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 6, 19, 'The LORD spoke to Moses, saying:', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 6, 20, 'This is the offering that Aaron and his sons shall offer to the LORD on the day when he is anointed: one-tenth of an ephah of choice flour as a regular offering, half of it in the morning and half in the evening.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 6, 21, 'It shall be made with oil on a griddle; you shall bring it well soaked, as a grain offering of baked pieces, and you shall present it as a pleasing odor to the LORD.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 6, 22, 'And so the priest, anointed from among Aaron"s descendants as a successor, shall prepare it; it is the LORD"s--a perpetual due--to be turned entirely into smoke.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 6, 23, 'Every grain offering of a priest shall be wholly burned; it shall not be eaten.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 6, 24, 'The LORD spoke to Moses, saying:', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 6, 25, 'Speak to Aaron and his sons, saying: This is the ritual of the sin offering. The sin offering shall be slaughtered before the LORD at the spot where the burnt offering is slaughtered; it is most holy.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 6, 26, 'The priest who offers it as a sin offering shall eat of it; it shall be eaten in a holy place, in the court of the tent of meeting.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 6, 27, 'Whatever touches its flesh shall become holy; and when any of its blood is spattered on a garment, you shall wash the bespattered part in a holy place.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 6, 28, 'An earthen vessel in which it was boiled shall be broken; but if it is boiled in a bronze vessel, that shall be scoured and rinsed in water.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 6, 29, 'Every male among the priests shall eat of it; it is most holy.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 6, 30, 'But no sin offering shall be eaten from which any blood is brought into the tent of meeting for atonement in the holy place; it shall be burned with fire.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(3, 'Ima', 'Leviticus', 7, 1, 'This is the ritual of the guilt offering. It is most holy;', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 7, 2, 'at the spot where the burnt offering is slaughtered, they shall slaughter the guilt offering, and its blood shall be dashed against all sides of the altar.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 7, 3, 'All its fat shall be offered: the broad tail, the fat that covers the entrails,', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 7, 4, 'the two kidneys with the fat that is on them at the loins, and the appendage of the liver, which shall be removed with the kidneys.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 7, 5, 'The priest shall turn them into smoke on the altar as an offering by fire to the LORD; it is a guilt offering.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 7, 6, 'Every male among the priests shall eat of it; it shall be eaten in a holy place; it is most holy.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 7, 7, 'The guilt offering is like the sin offering, there is the same ritual for them; the priest who makes atonement with it shall have it.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 7, 8, 'So, too, the priest who offers anyone"s burnt offering shall keep the skin of the burnt offering that he has offered.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 7, 9, 'And every grain offering baked in the oven, and all that is prepared in a pan or on a griddle, shall belong to the priest who offers it.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 7, 10, 'But every other grain offering, mixed with oil or dry, shall belong to all the sons of Aaron equally.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 7, 11, 'This is the ritual of the sacrifice of the offering of well-being that one may offer to the LORD.', 'en', 'NRSV-CE', 'Further Instructions'),
(3, 'Ima', 'Leviticus', 7, 12, 'If you offer it for thanksgiving, you shall offer with the thank offering unleavened cakes mixed with oil, unleavened wafers spread with oil, and cakes of choice flour well soaked in oil.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 7, 13, 'With your thanksgiving sacrifice of well-being you shall bring your offering with cakes of leavened bread.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 7, 14, 'From this you shall offer one cake from each offering, as a gift to the LORD; it shall belong to the priest who dashes the blood of the offering of well-being.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 7, 15, 'And the flesh of your thanksgiving sacrifice of well-being shall be eaten on the day it is offered; you shall not leave any of it until morning.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 7, 16, 'But if the sacrifice you offer is a votive offering or a freewill offering, it shall be eaten on the day that you offer your sacrifice, and what is left of it shall be eaten the next day;', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 7, 17, 'but what is left of the flesh of the sacrifice shall be burned up on the third day.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 7, 18, 'If any of the flesh of your sacrifice of well-being is eaten on the third day, it shall not be acceptable, nor shall it be credited to the one who offers it; it shall be an abomination, and the one who eats of it shall incur guilt.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 7, 19, 'Flesh that touches any unclean thing shall not be eaten; it shall be burned up. As for other flesh, all who are clean may eat such flesh.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 7, 20, 'But those who eat flesh from the LORD"s sacrifice of well-being while in a state of uncleanness shall be cut off from their kin.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 7, 21, 'When any one of you touches any unclean thing--human uncleanness or an unclean animal or any unclean creature--and then eats flesh from the LORD"s sacrifice of well-being, you shall be cut off from your kin.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 7, 22, 'The LORD spoke to Moses, saying:', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 7, 23, 'Speak to the people of Israel, saying: You shall eat no fat of ox or sheep or goat.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 7, 24, 'The fat of an animal that died or was torn by wild animals may be put to any other use, but you must not eat it.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 7, 25, 'If any one of you eats the fat from an animal of which an offering by fire may be made to the LORD, you who eat it shall be cut off from your kin.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 7, 26, 'You must not eat any blood whatever, either of bird or of animal, in any of your settlements.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 7, 27, 'Any one of you who eats any blood shall be cut off from your kin.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 7, 28, 'The LORD spoke to Moses, saying:', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 7, 29, 'Speak to the people of Israel, saying: Any one of you who would offer to the LORD your sacrifice of well-being must yourself bring to the LORD your offering from your sacrifice of well-being.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 7, 30, 'Your own hands shall bring the LORD"s offering by fire; you shall bring the fat with the breast, so that the breast may be raised as an elevation offering before the LORD.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 7, 31, 'The priest shall turn the fat into smoke on the altar, but the breast shall belong to Aaron and his sons.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 7, 32, 'And the right thigh from your sacrifices of well-being you shall give to the priest as an offering;', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 7, 33, 'the one among the sons of Aaron who offers the blood and fat of the offering of well-being shall have the right thigh for a portion.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 7, 34, 'For I have taken the breast of the elevation offering, and the thigh that is offered, from the people of Israel, from their sacrifices of well-being, and have given them to Aaron the priest and to his sons, as a perpetual due from the people of Israel.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 7, 35, 'This is the portion allotted to Aaron and to his sons from the offerings made by fire to the LORD, once they have been brought forward to serve the LORD as priests;', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 7, 36, 'these the LORD commanded to be given them, when he anointed them, as a perpetual due from the people of Israel throughout their generations.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 7, 37, 'This is the ritual of the burnt offering, the grain offering, the sin offering, the guilt offering, the offering of ordination, and the sacrifice of well-being,', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 7, 38, 'which the LORD commanded Moses on Mount Sinai, when he commanded the people of Israel to bring their offerings to the LORD, in the wilderness of Sinai.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(3, 'Ima', 'Leviticus', 8, 1, 'The LORD spoke to Moses, saying:', 'en', 'NRSV-CE', 'The Rites of Ordination'),
(3, 'Ima', 'Leviticus', 8, 2, 'Take Aaron and his sons with him, the vestments, the anointing oil, the bull of sin offering, the two rams, and the basket of unleavened bread;', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 8, 3, 'and assemble the whole congregation at the entrance of the tent of meeting.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 8, 4, 'And Moses did as the LORD commanded him. When the congregation was assembled at the entrance of the tent of meeting,', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 8, 5, 'Moses said to the congregation, "This is what the LORD has commanded to be done."', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 8, 6, 'Then Moses brought Aaron and his sons forward, and washed them with water.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 8, 7, 'He put the tunic on him, fastened the sash around him, clothed him with the robe, and put the ephod on him. He then put the decorated band of the ephod around him, tying the ephod to him with it.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 8, 8, 'He placed the breastpiece on him, and in the breastpiece he put the Urim and the Thummim.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 8, 9, 'And he set the turban on his head, and on the turban, in front, he set the golden ornament, the holy crown, as the LORD commanded Moses.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 8, 10, 'Then Moses took the anointing oil and anointed the tabernacle and all that was in it, and consecrated them.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 8, 11, 'He sprinkled some of it on the altar seven times, and anointed the altar and all its utensils, and the basin and its base, to consecrate them.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 8, 12, 'He poured some of the anointing oil on Aaron"s head and anointed him, to consecrate him.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 8, 13, 'And Moses brought forward Aaron"s sons, and clothed them with tunics, and fastened sashes around them, and tied headdresses on them, as the LORD commanded Moses.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 8, 14, 'He led forward the bull of sin offering; and Aaron and his sons laid their hands upon the head of the bull of sin offering,', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 8, 15, 'and it was slaughtered. Moses took the blood and with his finger put some on each of the horns of the altar, purifying the altar; then he poured out the blood at the base of the altar. Thus he consecrated it, to make atonement for it.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 8, 16, 'Moses took all the fat that was around the entrails, and the appendage of the liver, and the two kidneys with their fat, and turned them into smoke on the altar.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 8, 17, 'But the bull itself, its skin and flesh and its dung, he burned with fire outside the camp, as the LORD commanded Moses.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 8, 18, 'Then he brought forward the ram of burnt offering. Aaron and his sons laid their hands on the head of the ram,', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 8, 19, 'and it was slaughtered. Moses dashed the blood against all sides of the altar.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 8, 20, 'The ram was cut into its parts, and Moses turned into smoke the head and the parts and the suet.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 8, 21, 'And after the entrails and the legs were washed with water, Moses turned into smoke the whole ram on the altar; it was a burnt offering for a pleasing odor, an offering by fire to the LORD, as the LORD commanded Moses.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 8, 22, 'Then he brought forward the second ram, the ram of ordination. Aaron and his sons laid their hands on the head of the ram,', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 8, 23, 'and it was slaughtered. Moses took some of its blood and put it on the lobe of Aaron"s right ear and on the thumb of his right hand and on the big toe of his right foot.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 8, 24, 'After Aaron"s sons were brought forward, Moses put some of the blood on the lobes of their right ears and on the thumbs of their right hands and on the big toes of their right feet; and Moses dashed the rest of the blood against all sides of the altar.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 8, 25, 'He took the fat--the broad tail, all the fat that was around the entrails, the appendage of the liver, and the two kidneys with their fat--and the right thigh.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 8, 26, 'From the basket of unleavened bread that was before the LORD, he took one cake of unleavened bread, one cake of bread with oil, and one wafer, and placed them on the fat and on the right thigh.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 8, 27, 'He placed all these on the palms of Aaron and on the palms of his sons, and raised them as an elevation offering before the LORD.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 8, 28, 'Then Moses took them from their hands and turned them into smoke on the altar with the burnt offering. This was an ordination offering for a pleasing odor, an offering by fire to the LORD.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 8, 29, 'Moses took the breast and raised it as an elevation offering before the LORD; it was Moses" portion of the ram of ordination, as the LORD commanded Moses.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 8, 30, 'Then Moses took some of the anointing oil and some of the blood that was on the altar and sprinkled them on Aaron and his vestments, and also on his sons and their vestments. Thus he consecrated Aaron and his vestments, and also his sons and their vestments.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 8, 31, 'And Moses said to Aaron and his sons, "Boil the flesh at the entrance of the tent of meeting, and eat it there with the bread that is in the basket of ordination offerings, as I was commanded, "Aaron and his sons shall eat it";', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 8, 32, 'and what remains of the flesh and the bread you shall burn with fire.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 8, 33, 'You shall not go outside the entrance of the tent of meeting for seven days, until the day when your period of ordination is completed. For it will take seven days to ordain you;', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 8, 34, 'as has been done today, the LORD has commanded to be done to make atonement for you.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 8, 35, 'You shall remain at the entrance of the tent of meeting day and night for seven days, keeping the LORD"s charge so that you do not die; for so I am commanded."', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 8, 36, 'Aaron and his sons did all the things that the LORD commanded through Moses.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(3, 'Ima', 'Leviticus', 9, 1, 'On the eighth day Moses summoned Aaron and his sons and the elders of Israel.', 'en', 'NRSV-CE', 'Aaron"s Priesthood Inaugurated'),
(3, 'Ima', 'Leviticus', 9, 2, 'He said to Aaron, "Take a bull calf for a sin offering and a ram for a burnt offering, without blemish, and offer them before the LORD.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 9, 3, 'And say to the people of Israel, "Take a male goat for a sin offering; a calf and a lamb, yearlings without blemish, for a burnt offering;', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 9, 4, 'and an ox and a ram for an offering of well-being to sacrifice before the LORD; and a grain offering mixed with oil. For today the LORD will appear to you.""', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 9, 5, 'They brought what Moses commanded to the front of the tent of meeting; and the whole congregation drew near and stood before the LORD.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 9, 6, 'And Moses said, "This is the thing that the LORD commanded you to do, so that the glory of the LORD may appear to you."', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 9, 7, 'Then Moses said to Aaron, "Draw near to the altar and sacrifice your sin offering and your burnt offering, and make atonement for yourself and for the people; and sacrifice the offering of the people, and make atonement for them; as the LORD has commanded."', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 9, 8, 'Aaron drew near to the altar, and slaughtered the calf of the sin offering, which was for himself.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 9, 9, 'The sons of Aaron presented the blood to him, and he dipped his finger in the blood and put it on the horns of the altar; and the rest of the blood he poured out at the base of the altar.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 9, 10, 'But the fat, the kidneys, and the appendage of the liver from the sin offering he turned into smoke on the altar, as the LORD commanded Moses;', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 9, 11, 'and the flesh and the skin he burned with fire outside the camp.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 9, 12, 'Then he slaughtered the burnt offering. Aaron"s sons brought him the blood, and he dashed it against all sides of the altar.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 9, 13, 'And they brought him the burnt offering piece by piece, and the head, which he turned into smoke on the altar.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 9, 14, 'He washed the entrails and the legs and, with the burnt offering, turned them into smoke on the altar.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 9, 15, 'Next he presented the people"s offering. He took the goat of the sin offering that was for the people, and slaughtered it, and presented it as a sin offering like the first one.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 9, 16, 'He presented the burnt offering, and sacrificed it according to regulation.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 9, 17, 'He presented the grain offering, and, taking a handful of it, he turned it into smoke on the altar, in addition to the burnt offering of the morning.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 9, 18, 'He slaughtered the ox and the ram as a sacrifice of well-being for the people. Aaron"s sons brought him the blood, which he dashed against all sides of the altar,', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 9, 19, 'and the fat of the ox and of the ram--the broad tail, the fat that covers the entrails, the two kidneys and the fat on them, and the appendage of the liver.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 9, 20, 'They first laid the fat on the breasts, and the fat was turned into smoke on the altar;', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 9, 21, 'and the breasts and the right thigh Aaron raised as an elevation offering before the LORD, as Moses had commanded.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 9, 22, 'Aaron lifted his hands toward the people and blessed them; and he came down after sacrificing the sin offering, the burnt offering, and the offering of well-being.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 9, 23, 'Moses and Aaron entered the tent of meeting, and then came out and blessed the people; and the glory of the LORD appeared to all the people.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 9, 24, 'Fire came out from the LORD and consumed the burnt offering and the fat on the altar; and when all the people saw it, they shouted and fell on their faces.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(3, 'Ima', 'Leviticus', 10, 1, 'Now Aaron"s sons, Nadab and Abihu, each took his censer, put fire in it, and laid incense on it; and they offered unholy fire before the LORD, such as he had not commanded them.', 'en', 'NRSV-CE', 'Nadab and Abihu'),
(3, 'Ima', 'Leviticus', 10, 2, 'And fire came out from the presence of the LORD and consumed them, and they died before the LORD.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 10, 3, 'Then Moses said to Aaron, "This is what the LORD meant when he said,
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(3, 'Ima', 'Leviticus', 11, 1, 'The LORD spoke to Moses and Aaron, saying to them:', 'en', 'NRSV-CE', 'Clean and Unclean Foods'),
(3, 'Ima', 'Leviticus', 11, 2, 'Speak to the people of Israel, saying:
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(3, 'Ima', 'Leviticus', 12, 1, 'The LORD spoke to Moses, saying:', 'en', 'NRSV-CE', 'Purification of Women after Childbirth'),
(3, 'Ima', 'Leviticus', 12, 2, 'Speak to the people of Israel, saying:
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(3, 'Ima', 'Leviticus', 13, 1, 'The LORD spoke to Moses and Aaron, saying:', 'en', 'NRSV-CE', 'Leprosy, Varieties and Symptoms'),
(3, 'Ima', 'Leviticus', 13, 2, 'When a person has on the skin of his body a swelling or an eruption or a spot, and it turns into a leprous disease on the skin of his body, he shall be brought to Aaron the priest or to one of his sons the priests.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 13, 3, 'The priest shall examine the disease on the skin of his body, and if the hair in the diseased area has turned white and the disease appears to be deeper than the skin of his body, it is a leprous disease; after the priest has examined him he shall pronounce him ceremonially unclean.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 13, 4, 'But if the spot is white in the skin of his body, and appears no deeper than the skin, and the hair in it has not turned white, the priest shall confine the diseased person for seven days.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 13, 5, 'The priest shall examine him on the seventh day, and if he sees that the disease is checked and the disease has not spread in the skin, then the priest shall confine him seven days more.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 13, 6, 'The priest shall examine him again on the seventh day, and if the disease has abated and the disease has not spread in the skin, the priest shall pronounce him clean; it is only an eruption; and he shall wash his clothes, and be clean.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 13, 7, 'But if the eruption spreads in the skin after he has shown himself to the priest for his cleansing, he shall appear again before the priest.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 13, 8, 'The priest shall make an examination, and if the eruption has spread in the skin, the priest shall pronounce him unclean; it is a leprous disease.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 13, 9, 'When a person contracts a leprous disease, he shall be brought to the priest.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 13, 10, 'The priest shall make an examination, and if there is a white swelling in the skin that has turned the hair white, and there is quick raw flesh in the swelling,', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 13, 11, 'it is a chronic leprous disease in the skin of his body. The priest shall pronounce him unclean; he shall not confine him, for he is unclean.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 13, 12, 'But if the disease breaks out in the skin, so that it covers all the skin of the diseased person from head to foot, so far as the priest can see,', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 13, 13, 'then the priest shall make an examination, and if the disease has covered all his body, he shall pronounce him clean of the disease; since it has all turned white, he is clean.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 13, 14, 'But if raw flesh ever appears on him, he shall be unclean;', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 13, 15, 'the priest shall examine the raw flesh and pronounce him unclean. Raw flesh is unclean, for it is a leprous disease.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 13, 16, 'But if the raw flesh again turns white, he shall come to the priest;', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 13, 17, 'the priest shall examine him, and if the disease has turned white, the priest shall pronounce the diseased person clean. He is clean.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 13, 18, 'When there is on the skin of one"s body a boil that has healed,', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 13, 19, 'and in the place of the boil there appears a white swelling or a reddish-white spot, it shall be shown to the priest.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 13, 20, 'The priest shall make an examination, and if it appears deeper than the skin and its hair has turned white, the priest shall pronounce him unclean; this is a leprous disease, broken out in the boil.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 13, 21, 'But if the priest examines it and the hair on it is not white, nor is it deeper than the skin but has abated, the priest shall confine him seven days.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 13, 22, 'If it spreads in the skin, the priest shall pronounce him unclean; it is diseased.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 13, 23, 'But if the spot remains in one place and does not spread, it is the scar of the boil; the priest shall pronounce him clean.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 13, 24, 'Or, when the body has a burn on the skin and the raw flesh of the burn becomes a spot, reddish-white or white,', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 13, 25, 'the priest shall examine it. If the hair in the spot has turned white and it appears deeper than the skin, it is a leprous disease; it has broken out in the burn, and the priest shall pronounce him unclean. This is a leprous disease.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 13, 26, 'But if the priest examines it and the hair in the spot is not white, and it is no deeper than the skin but has abated, the priest shall confine him seven days.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 13, 27, 'The priest shall examine him the seventh day; if it is spreading in the skin, the priest shall pronounce him unclean. This is a leprous disease.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 13, 28, 'But if the spot remains in one place and does not spread in the skin but has abated, it is a swelling from the burn, and the priest shall pronounce him clean; for it is the scar of the burn.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 13, 29, 'When a man or woman has a disease on the head or in the beard,', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 13, 30, 'the priest shall examine the disease. If it appears deeper than the skin and the hair in it is yellow and thin, the priest shall pronounce him unclean; it is an itch, a leprous disease of the head or the beard.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 13, 31, 'If the priest examines the itching disease, and it appears no deeper than the skin and there is no black hair in it, the priest shall confine the person with the itching disease for seven days.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 13, 32, 'On the seventh day the priest shall examine the itch; if the itch has not spread, and there is no yellow hair in it, and the itch appears to be no deeper than the skin,', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 13, 33, 'he shall shave, but the itch he shall not shave. The priest shall confine the person with the itch for seven days more.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 13, 34, 'On the seventh day the priest shall examine the itch; if the itch has not spread in the skin and it appears to be no deeper than the skin, the priest shall pronounce him clean. He shall wash his clothes and be clean.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 13, 35, 'But if the itch spreads in the skin after he was pronounced clean,', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 13, 36, 'the priest shall examine him. If the itch has spread in the skin, the priest need not seek for the yellow hair; he is unclean.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 13, 37, 'But if in his eyes the itch is checked, and black hair has grown in it, the itch is healed, he is clean; and the priest shall pronounce him clean.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 13, 38, 'When a man or a woman has spots on the skin of the body, white spots,', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 13, 39, 'the priest shall make an examination, and if the spots on the skin of the body are of a dull white, it is a rash that has broken out on the skin; he is clean.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 13, 40, 'If anyone loses the hair from his head, he is bald but he is clean.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 13, 41, 'If he loses the hair from his forehead and temples, he has baldness of the forehead but he is clean.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 13, 42, 'But if there is on the bald head or the bald forehead a reddish-white diseased spot, it is a leprous disease breaking out on his bald head or his bald forehead.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 13, 43, 'The priest shall examine him; if the diseased swelling is reddish-white on his bald head or on his bald forehead, which resembles a leprous disease in the skin of the body,', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 13, 44, 'he is leprous, he is unclean. The priest shall pronounce him unclean; the disease is on his head.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 13, 45, 'The person who has the leprous disease shall wear torn clothes and let the hair of his head be disheveled; and he shall cover his upper lip and cry out, "Unclean, unclean."', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 13, 46, 'He shall remain unclean as long as he has the disease; he is unclean. He shall live alone; his dwelling shall be outside the camp.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 13, 47, 'Concerning clothing: when a leprous disease appears in it, in woolen or linen cloth,', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 13, 48, 'in warp or woof of linen or wool, or in a skin or in anything made of skin,', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 13, 49, 'if the disease shows greenish or reddish in the garment, whether in warp or woof or in skin or in anything made of skin, it is a leprous disease and shall be shown to the priest.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 13, 50, 'The priest shall examine the disease, and put the diseased article aside for seven days.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 13, 51, 'He shall examine the disease on the seventh day. If the disease has spread in the cloth, in warp or woof, or in the skin, whatever be the use of the skin, this is a spreading leprous disease; it is unclean.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 13, 52, 'He shall burn the clothing, whether diseased in warp or woof, woolen or linen, or anything of skin, for it is a spreading leprous disease; it shall be burned in fire.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 13, 53, 'If the priest makes an examination, and the disease has not spread in the clothing, in warp or woof or in anything of skin,', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 13, 54, 'the priest shall command them to wash the article in which the disease appears, and he shall put it aside seven days more.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 13, 55, 'The priest shall examine the diseased article after it has been washed. If the diseased spot has not changed color, though the disease has not spread, it is unclean; you shall burn it in fire, whether the leprous spot is on the inside or on the outside.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 13, 56, 'If the priest makes an examination, and the disease has abated after it is washed, he shall tear the spot out of the cloth, in warp or woof, or out of skin.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 13, 57, 'If it appears again in the garment, in warp or woof, or in anything of skin, it is spreading; you shall burn with fire that in which the disease appears.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 13, 58, 'But the cloth, warp or woof, or anything of skin from which the disease disappears when you have washed it, shall then be washed a second time, and it shall be clean.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 13, 59, 'This is the ritual for a leprous disease in a cloth of wool or linen, either in warp or woof, or in anything of skin, to decide whether it is clean or unclean.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(3, 'Ima', 'Leviticus', 14, 1, 'The LORD spoke to Moses, saying:', 'en', 'NRSV-CE', 'Purification of Lepers and Leprous Houses'),
(3, 'Ima', 'Leviticus', 14, 2, 'This shall be the ritual for the leprous person at the time of his cleansing:
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(3, 'Ima', 'Leviticus', 15, 1, 'The LORD spoke to Moses and Aaron, saying:', 'en', 'NRSV-CE', 'Concerning Bodily Discharges'),
(3, 'Ima', 'Leviticus', 15, 2, 'Speak to the people of Israel and say to them:
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(3, 'Ima', 'Leviticus', 16, 1, 'The LORD spoke to Moses after the death of the two sons of Aaron, when they drew near before the LORD and died.', 'en', 'NRSV-CE', 'The Day of Atonement'),
(3, 'Ima', 'Leviticus', 16, 2, 'The LORD said to Moses:
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(3, 'Ima', 'Leviticus', 17, 1, 'The LORD spoke to Moses:', 'en', 'NRSV-CE', 'The Slaughtering of Animals'),
(3, 'Ima', 'Leviticus', 17, 2, 'Speak to Aaron and his sons and to all the people of Israel and say to them: This is what the LORD has commanded.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 17, 3, 'If anyone of the house of Israel slaughters an ox or a lamb or a goat in the camp, or slaughters it outside the camp,', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 17, 4, 'and does not bring it to the entrance of the tent of meeting, to present it as an offering to the LORD before the tabernacle of the LORD, he shall be held guilty of bloodshed; he has shed blood, and he shall be cut off from the people.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 17, 5, 'This is in order that the people of Israel may bring their sacrifices that they offer in the open field, that they may bring them to the LORD, to the priest at the entrance of the tent of meeting, and offer them as sacrifices of well-being to the LORD.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 17, 6, 'The priest shall dash the blood against the altar of the LORD at the entrance of the tent of meeting, and turn the fat into smoke as a pleasing odor to the LORD,', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 17, 7, 'so that they may no longer offer their sacrifices for goat-demons, to whom they prostitute themselves. This shall be a statute forever to them throughout their generations.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 17, 8, 'And say to them further: Anyone of the house of Israel or of the aliens who reside among them who offers a burnt offering or sacrifice,', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 17, 9, 'and does not bring it to the entrance of the tent of meeting, to sacrifice it to the LORD, shall be cut off from the people.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 17, 10, 'If anyone of the house of Israel or of the aliens who reside among them eats any blood, I will set my face against that person who eats blood, and will cut that person off from the people.', 'en', 'NRSV-CE', 'Eating Blood Prohibited'),
(3, 'Ima', 'Leviticus', 17, 11, 'For the life of the flesh is in the blood; and I have given it to you for making atonement for your lives on the altar; for, as life, it is the blood that makes atonement.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 17, 12, 'Therefore I have said to the people of Israel: No person among you shall eat blood, nor shall any alien who resides among you eat blood.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 17, 13, 'And anyone of the people of Israel, or of the aliens who reside among them, who hunts down an animal or bird that may be eaten shall pour out its blood and cover it with earth.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 17, 14, 'For the life of every creature--its blood is its life; therefore I have said to the people of Israel: You shall not eat the blood of any creature, for the life of every creature is its blood; whoever eats it shall be cut off.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 17, 15, 'All persons, citizens or aliens, who eat what dies of itself or what has been torn by wild animals, shall wash their clothes, and bathe themselves in water, and be unclean until the evening; then they shall be clean.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 17, 16, 'But if they do not wash themselves or bathe their body, they shall bear their guilt.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(3, 'Ima', 'Leviticus', 18, 1, 'The LORD spoke to Moses, saying:', 'en', 'NRSV-CE', 'Sexual Relations'),
(3, 'Ima', 'Leviticus', 18, 2, 'Speak to the people of Israel and say to them: I am the LORD your God.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 18, 3, 'You shall not do as they do in the land of Egypt, where you lived, and you shall not do as they do in the land of Canaan, to which I am bringing you. You shall not follow their statutes.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 18, 4, 'My ordinances you shall observe and my statutes you shall keep, following them: I am the LORD your God.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 18, 5, 'You shall keep my statutes and my ordinances; by doing so one shall live: I am the LORD.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 18, 6, 'None of you shall approach anyone near of kin to uncover nakedness: I am the LORD.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 18, 7, 'You shall not uncover the nakedness of your father, which is the nakedness of your mother; she is your mother, you shall not uncover her nakedness.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 18, 8, 'You shall not uncover the nakedness of your father"s wife; it is the nakedness of your father.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 18, 9, 'You shall not uncover the nakedness of your sister, your father"s daughter or your mother"s daughter, whether born at home or born abroad.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 18, 10, 'You shall not uncover the nakedness of your son"s daughter or of your daughter"s daughter, for their nakedness is your own nakedness.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 18, 11, 'You shall not uncover the nakedness of your father"s wife"s daughter, begotten by your father, since she is your sister.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 18, 12, 'You shall not uncover the nakedness of your father"s sister; she is your father"s flesh.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 18, 13, 'You shall not uncover the nakedness of your mother"s sister, for she is your mother"s flesh.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 18, 14, 'You shall not uncover the nakedness of your father"s brother, that is, you shall not approach his wife; she is your aunt.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 18, 15, 'You shall not uncover the nakedness of your daughter-in-law: she is your son"s wife; you shall not uncover her nakedness.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 18, 16, 'You shall not uncover the nakedness of your brother"s wife; it is your brother"s nakedness.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 18, 17, 'You shall not uncover the nakedness of a woman and her daughter, and you shall not take her son"s daughter or her daughter"s daughter to uncover her nakedness; they are your flesh; it is depravity.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 18, 18, 'And you shall not take a woman as a rival to her sister, uncovering her nakedness while her sister is still alive.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 18, 19, 'You shall not approach a woman to uncover her nakedness while she is in her menstrual uncleanness.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 18, 20, 'You shall not have sexual relations with your kinsman"s wife, and defile yourself with her.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 18, 21, 'You shall not give any of your offspring to sacrifice them to Molech, and so profane the name of your God: I am the LORD.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 18, 22, 'You shall not lie with a male as with a woman; it is an abomination.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 18, 23, 'You shall not have sexual relations with any animal and defile yourself with it, nor shall any woman give herself to an animal to have sexual relations with it: it is perversion.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 18, 24, 'Do not defile yourselves in any of these ways, for by all these practices the nations I am casting out before you have defiled themselves.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 18, 25, 'Thus the land became defiled; and I punished it for its iniquity, and the land vomited out its inhabitants.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 18, 26, 'But you shall keep my statutes and my ordinances and commit none of these abominations, either the citizen or the alien who resides among you', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 18, 27, '(for the inhabitants of the land, who were before you, committed all of these abominations, and the land became defiled);', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 18, 28, 'otherwise the land will vomit you out for defiling it, as it vomited out the nation that was before you.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 18, 29, 'For whoever commits any of these abominations shall be cut off from their people.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 18, 30, 'So keep my charge not to commit any of these abominations that were done before you, and not to defile yourselves by them: I am the LORD your God.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(3, 'Ima', 'Leviticus', 19, 1, 'The LORD spoke to Moses, saying:', 'en', 'NRSV-CE', 'Ritual and Moral Holiness'),
(3, 'Ima', 'Leviticus', 19, 2, 'Speak to all the congregation of the people of Israel and say to them: You shall be holy, for I the LORD your God am holy.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 19, 3, 'You shall each revere your mother and father, and you shall keep my sabbaths: I am the LORD your God.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 19, 4, 'Do not turn to idols or make cast images for yourselves: I am the LORD your God.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 19, 5, 'When you offer a sacrifice of well-being to the LORD, offer it in such a way that it is acceptable in your behalf.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 19, 6, 'It shall be eaten on the same day you offer it, or on the next day; and anything left over until the third day shall be consumed in fire.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 19, 7, 'If it is eaten at all on the third day, it is an abomination; it will not be acceptable.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 19, 8, 'All who eat it shall be subject to punishment, because they have profaned what is holy to the LORD; and any such person shall be cut off from the people.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 19, 9, 'When you reap the harvest of your land, you shall not reap to the very edges of your field, or gather the gleanings of your harvest.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 19, 10, 'You shall not strip your vineyard bare, or gather the fallen grapes of your vineyard; you shall leave them for the poor and the alien: I am the LORD your God.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 19, 11, 'You shall not steal; you shall not deal falsely; and you shall not lie to one another.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 19, 12, 'And you shall not swear falsely by my name, profaning the name of your God: I am the LORD.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 19, 13, 'You shall not defraud your neighbor; you shall not steal; and you shall not keep for yourself the wages of a laborer until morning.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 19, 14, 'You shall not revile the deaf or put a stumbling block before the blind; you shall fear your God: I am the LORD.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 19, 15, 'You shall not render an unjust judgment; you shall not be partial to the poor or defer to the great: with justice you shall judge your neighbor.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 19, 16, 'You shall not go around as a slanderer among your people, and you shall not profit by the blood of your neighbor: I am the LORD.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 19, 17, 'You shall not hate in your heart anyone of your kin; you shall reprove your neighbor, or you will incur guilt yourself.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 19, 18, 'You shall not take vengeance or bear a grudge against any of your people, but you shall love your neighbor as yourself: I am the LORD.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 19, 19, 'You shall keep my statutes. You shall not let your animals breed with a different kind; you shall not sow your field with two kinds of seed; nor shall you put on a garment made of two different materials.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 19, 20, 'If a man has sexual relations with a woman who is a slave, designated for another man but not ransomed or given her freedom, an inquiry shall be held. They shall not be put to death, since she has not been freed;', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 19, 21, 'but he shall bring a guilt offering for himself to the LORD, at the entrance of the tent of meeting, a ram as guilt offering.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 19, 22, 'And the priest shall make atonement for him with the ram of guilt offering before the LORD for his sin that he committed; and the sin he committed shall be forgiven him.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 19, 23, 'When you come into the land and plant all kinds of trees for food, then you shall regard their fruit as forbidden; three years it shall be forbidden to you, it must not be eaten.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 19, 24, 'In the fourth year all their fruit shall be set apart for rejoicing in the LORD.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 19, 25, 'But in the fifth year you may eat of their fruit, that their yield may be increased for you: I am the LORD your God.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 19, 26, 'You shall not eat anything with its blood. You shall not practice augury or witchcraft.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 19, 27, 'You shall not round off the hair on your temples or mar the edges of your beard.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 19, 28, 'You shall not make any gashes in your flesh for the dead or tattoo any marks upon you: I am the LORD.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 19, 29, 'Do not profane your daughter by making her a prostitute, that the land not become prostituted and full of depravity.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 19, 30, 'You shall keep my sabbaths and reverence my sanctuary: I am the LORD.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 19, 31, 'Do not turn to mediums or wizards; do not seek them out, to be defiled by them: I am the LORD your God.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 19, 32, 'You shall rise before the aged, and defer to the old; and you shall fear your God: I am the LORD.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 19, 33, 'When an alien resides with you in your land, you shall not oppress the alien.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 19, 34, 'The alien who resides with you shall be to you as the citizen among you; you shall love the alien as yourself, for you were aliens in the land of Egypt: I am the LORD your God.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 19, 35, 'You shall not cheat in measuring length, weight, or quantity.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 19, 36, 'You shall have honest balances, honest weights, an honest ephah, and an honest hin: I am the LORD your God, who brought you out of the land of Egypt.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 19, 37, 'You shall keep all my statutes and all my ordinances, and observe them: I am the LORD.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(3, 'Ima', 'Leviticus', 20, 1, 'The LORD spoke to Moses, saying:', 'en', 'NRSV-CE', 'Penalties for Violations of Holiness'),
(3, 'Ima', 'Leviticus', 20, 2, 'Say further to the people of Israel:
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(3, 'Ima', 'Leviticus', 21, 1, 'The LORD said to Moses: Speak to the priests, the sons of Aaron, and say to them:
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(3, 'Ima', 'Leviticus', 22, 1, 'The LORD spoke to Moses, saying:', 'en', 'NRSV-CE', 'The Use of Holy Offerings'),
(3, 'Ima', 'Leviticus', 22, 2, 'Direct Aaron and his sons to deal carefully with the sacred donations of the people of Israel, which they dedicate to me, so that they may not profane my holy name; I am the LORD.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 22, 3, 'Say to them: If anyone among all your offspring throughout your generations comes near the sacred donations, which the people of Israel dedicate to the LORD, while he is in a state of uncleanness, that person shall be cut off from my presence: I am the LORD.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 22, 4, 'No one of Aaron"s offspring who has a leprous disease or suffers a discharge may eat of the sacred donations until he is clean. Whoever touches anything made unclean by a corpse or a man who has had an emission of semen,', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 22, 5, 'and whoever touches any swarming thing by which he may be made unclean or any human being by whom he may be made unclean--whatever his uncleanness may be--', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 22, 6, 'the person who touches any such shall be unclean until evening and shall not eat of the sacred donations unless he has washed his body in water.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 22, 7, 'When the sun sets he shall be clean; and afterward he may eat of the sacred donations, for they are his food.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 22, 8, 'That which died or was torn by wild animals he shall not eat, becoming unclean by it: I am the LORD.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 22, 9, 'They shall keep my charge, so that they may not incur guilt and die in the sanctuary for having profaned it: I am the LORD; I sanctify them.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 22, 10, 'No lay person shall eat of the sacred donations. No bound or hired servant of the priest shall eat of the sacred donations;', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 22, 11, 'but if a priest acquires anyone by purchase, the person may eat of them; and those that are born in his house may eat of his food.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 22, 12, 'If a priest"s daughter marries a layman, she shall not eat of the offering of the sacred donations;', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 22, 13, 'but if a priest"s daughter is widowed or divorced, without offspring, and returns to her father"s house, as in her youth, she may eat of her father"s food. No lay person shall eat of it.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 22, 14, 'If a man eats of the sacred donation unintentionally, he shall add one-fifth of its value to it, and give the sacred donation to the priest.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 22, 15, 'No one shall profane the sacred donations of the people of Israel, which they offer to the LORD,', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 22, 16, 'causing them to bear guilt requiring a guilt offering, by eating their sacred donations: for I am the LORD; I sanctify them.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 22, 17, 'The LORD spoke to Moses, saying:', 'en', 'NRSV-CE', 'Acceptable Offerings'),
(3, 'Ima', 'Leviticus', 22, 18, 'Speak to Aaron and his sons and all the people of Israel and say to them: When anyone of the house of Israel or of the aliens residing in Israel presents an offering, whether in payment of a vow or as a freewill offering that is offered to the LORD as a burnt offering,', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 22, 19, 'to be acceptable in your behalf it shall be a male without blemish, of the cattle or the sheep or the goats.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 22, 20, 'You shall not offer anything that has a blemish, for it will not be acceptable in your behalf.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 22, 21, 'When anyone offers a sacrifice of well-being to the LORD, in fulfillment of a vow or as a freewill offering, from the herd or from the flock, to be acceptable it must be perfect; there shall be no blemish in it.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 22, 22, 'Anything blind, or injured, or maimed, or having a discharge or an itch or scabs--these you shall not offer to the LORD or put any of them on the altar as offerings by fire to the LORD.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 22, 23, 'An ox or a lamb that has a limb too long or too short you may present for a freewill offering; but it will not be accepted for a vow.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 22, 24, 'Any animal that has its testicles bruised or crushed or torn or cut, you shall not offer to the LORD; such you shall not do within your land,', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 22, 25, 'nor shall you accept any such animals from a foreigner to offer as food to your God; since they are mutilated, with a blemish in them, they shall not be accepted in your behalf.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 22, 26, 'The LORD spoke to Moses, saying:', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 22, 27, 'When an ox or a sheep or a goat is born, it shall remain seven days with its mother, and from the eighth day on it shall be acceptable as the LORD"s offering by fire.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 22, 28, 'But you shall not slaughter, from the herd or the flock, an animal with its young on the same day.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 22, 29, 'When you sacrifice a thanksgiving offering to the LORD, you shall sacrifice it so that it may be acceptable in your behalf.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 22, 30, 'It shall be eaten on the same day; you shall not leave any of it until morning: I am the LORD.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 22, 31, 'Thus you shall keep my commandments and observe them: I am the LORD.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 22, 32, 'You shall not profane my holy name, that I may be sanctified among the people of Israel: I am the LORD; I sanctify you,', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 22, 33, 'I who brought you out of the land of Egypt to be your God: I am the LORD.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(3, 'Ima', 'Leviticus', 23, 1, 'The LORD spoke to Moses, saying:', 'en', 'NRSV-CE', 'Appointed Festivals'),
(3, 'Ima', 'Leviticus', 23, 2, 'Speak to the people of Israel and say to them: These are the appointed festivals of the LORD that you shall proclaim as holy convocations, my appointed festivals.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 23, 3, 'Six days shall work be done; but the seventh day is a sabbath of complete rest, a holy convocation; you shall do no work: it is a sabbath to the LORD throughout your settlements.', 'en', 'NRSV-CE', 'The Sabbath, Passover, and Unleavened Bread'),
(3, 'Ima', 'Leviticus', 23, 4, 'These are the appointed festivals of the LORD, the holy convocations, which you shall celebrate at the time appointed for them.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 23, 5, 'In the first month, on the fourteenth day of the month, at twilight, there shall be a passover offering to the LORD,', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 23, 6, 'and on the fifteenth day of the same month is the festival of unleavened bread to the LORD; seven days you shall eat unleavened bread.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 23, 7, 'On the first day you shall have a holy convocation; you shall not work at your occupations.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 23, 8, 'For seven days you shall present the LORD"s offerings by fire; on the seventh day there shall be a holy convocation: you shall not work at your occupations.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 23, 9, 'The LORD spoke to Moses:', 'en', 'NRSV-CE', 'The Offering of First Fruits'),
(3, 'Ima', 'Leviticus', 23, 10, 'Speak to the people of Israel and say to them: When you enter the land that I am giving you and you reap its harvest, you shall bring the sheaf of the first fruits of your harvest to the priest.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 23, 11, 'He shall raise the sheaf before the LORD, that you may find acceptance; on the day after the sabbath the priest shall raise it.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 23, 12, 'On the day when you raise the sheaf, you shall offer a lamb a year old, without blemish, as a burnt offering to the LORD.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 23, 13, 'And the grain offering with it shall be two-tenths of an ephah of choice flour mixed with oil, an offering by fire of pleasing odor to the LORD; and the drink offering with it shall be of wine, one-fourth of a hin.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 23, 14, 'You shall eat no bread or parched grain or fresh ears until that very day, until you have brought the offering of your God: it is a statute forever throughout your generations in all your settlements.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 23, 15, 'And from the day after the sabbath, from the day on which you bring the sheaf of the elevation offering, you shall count off seven weeks; they shall be complete.', 'en', 'NRSV-CE', 'The Festival of Weeks'),
(3, 'Ima', 'Leviticus', 23, 16, 'You shall count until the day after the seventh sabbath, fifty days; then you shall present an offering of new grain to the LORD.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 23, 17, 'You shall bring from your settlements two loaves of bread as an elevation offering, each made of two-tenths of an ephah; they shall be of choice flour, baked with leaven, as first fruits to the LORD.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 23, 18, 'You shall present with the bread seven lambs a year old without blemish, one young bull, and two rams; they shall be a burnt offering to the LORD, along with their grain offering and their drink offerings, an offering by fire of pleasing odor to the LORD.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 23, 19, 'You shall also offer one male goat for a sin offering, and two male lambs a year old as a sacrifice of well-being.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 23, 20, 'The priest shall raise them with the bread of the first fruits as an elevation offering before the LORD, together with the two lambs; they shall be holy to the LORD for the priest.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 23, 21, 'On that same day you shall make proclamation; you shall hold a holy convocation; you shall not work at your occupations. This is a statute forever in all your settlements throughout your generations.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 23, 22, 'When you reap the harvest of your land, you shall not reap to the very edges of your field, or gather the gleanings of your harvest; you shall leave them for the poor and for the alien: I am the LORD your God.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 23, 23, 'The LORD spoke to Moses, saying:', 'en', 'NRSV-CE', 'The Festival of Trumpets'),
(3, 'Ima', 'Leviticus', 23, 24, 'Speak to the people of Israel, saying: In the seventh month, on the first day of the month, you shall observe a day of complete rest, a holy convocation commemorated with trumpet blasts.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 23, 25, 'You shall not work at your occupations; and you shall present the LORD"s offering by fire.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 23, 26, 'The LORD spoke to Moses, saying:', 'en', 'NRSV-CE', 'The Day of Atonement'),
(3, 'Ima', 'Leviticus', 23, 27, 'Now, the tenth day of this seventh month is the day of atonement; it shall be a holy convocation for you: you shall deny yourselves and present the LORD"s offering by fire;', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 23, 28, 'and you shall do no work during that entire day; for it is a day of atonement, to make atonement on your behalf before the LORD your God.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 23, 29, 'For anyone who does not practice self-denial during that entire day shall be cut off from the people.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 23, 30, 'And anyone who does any work during that entire day, such a one I will destroy from the midst of the people.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 23, 31, 'You shall do no work: it is a statute forever throughout your generations in all your settlements.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 23, 32, 'It shall be to you a sabbath of complete rest, and you shall deny yourselves; on the ninth day of the month at evening, from evening to evening you shall keep your sabbath.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 23, 33, 'The LORD spoke to Moses, saying:', 'en', 'NRSV-CE', 'The Festival of Booths'),
(3, 'Ima', 'Leviticus', 23, 34, 'Speak to the people of Israel, saying: On the fifteenth day of this seventh month, and lasting seven days, there shall be the festival of booths to the LORD.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 23, 35, 'The first day shall be a holy convocation; you shall not work at your occupations.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 23, 36, 'Seven days you shall present the LORD"s offerings by fire; on the eighth day you shall observe a holy convocation and present the LORD"s offerings by fire; it is a solemn assembly; you shall not work at your occupations.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 23, 37, 'These are the appointed festivals of the LORD, which you shall celebrate as times of holy convocation, for presenting to the LORD offerings by fire--burnt offerings and grain offerings, sacrifices and drink offerings, each on its proper day--', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 23, 38, 'apart from the sabbaths of the LORD, and apart from your gifts, and apart from all your votive offerings, and apart from all your freewill offerings, which you give to the LORD.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 23, 39, 'Now, the fifteenth day of the seventh month, when you have gathered in the produce of the land, you shall keep the festival of the LORD, lasting seven days; a complete rest on the first day, and a complete rest on the eighth day.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 23, 40, 'On the first day you shall take the fruit of majestic trees, branches of palm trees, boughs of leafy trees, and willows of the brook; and you shall rejoice before the LORD your God for seven days.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 23, 41, 'You shall keep it as a festival to the LORD seven days in the year; you shall keep it in the seventh month as a statute forever throughout your generations.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 23, 42, 'You shall live in booths for seven days; all that are citizens in Israel shall live in booths,', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 23, 43, 'so that your generations may know that I made the people of Israel live in booths when I brought them out of the land of Egypt: I am the LORD your God.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 23, 44, 'Thus Moses declared to the people of Israel the appointed festivals of the LORD.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(3, 'Ima', 'Leviticus', 24, 1, 'The LORD spoke to Moses, saying:', 'en', 'NRSV-CE', 'The Lamp'),
(3, 'Ima', 'Leviticus', 24, 2, 'Command the people of Israel to bring you pure oil of beaten olives for the lamp, that a light may be kept burning regularly.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 24, 3, 'Aaron shall set it up in the tent of meeting, outside the curtain of the covenant, to burn from evening to morning before the LORD regularly; it shall be a statute forever throughout your generations.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 24, 4, 'He shall set up the lamps on the lampstand of pure gold before the LORD regularly.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 24, 5, 'You shall take choice flour, and bake twelve loaves of it; two-tenths of an ephah shall be in each loaf.', 'en', 'NRSV-CE', 'The Bread for the Tabernacle'),
(3, 'Ima', 'Leviticus', 24, 6, 'You shall place them in two rows, six in a row, on the table of pure gold.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 24, 7, 'You shall put pure frankincense with each row, to be a token offering for the bread, as an offering by fire to the LORD.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 24, 8, 'Every sabbath day Aaron shall set them in order before the LORD regularly as a commitment of the people of Israel, as a covenant forever.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 24, 9, 'They shall be for Aaron and his descendants, who shall eat them in a holy place, for they are most holy portions for him from the offerings by fire to the LORD, a perpetual due.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 24, 10, 'A man whose mother was an Israelite and whose father was an Egyptian came out among the people of Israel; and the Israelite woman"s son and a certain Israelite began fighting in the camp.', 'en', 'NRSV-CE', 'Blasphemy and Its Punishment'),
(3, 'Ima', 'Leviticus', 24, 11, 'The Israelite woman"s son blasphemed the Name in a curse. And they brought him to Moses--now his mother"s name was Shelomith, daughter of Dibri, of the tribe of Dan--', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 24, 12, 'and they put him in custody, until the decision of the LORD should be made clear to them.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 24, 13, 'The LORD said to Moses, saying:', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 24, 14, 'Take the blasphemer outside the camp; and let all who were within hearing lay their hands on his head, and let the whole congregation stone him.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 24, 15, 'And speak to the people of Israel, saying: Anyone who curses God shall bear the sin.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 24, 16, 'One who blasphemes the name of the LORD shall be put to death; the whole congregation shall stone the blasphemer. Aliens as well as citizens, when they blaspheme the Name, shall be put to death.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 24, 17, 'Anyone who kills a human being shall be put to death.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 24, 18, 'Anyone who kills an animal shall make restitution for it, life for life.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 24, 19, 'Anyone who maims another shall suffer the same injury in return:', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 24, 20, 'fracture for fracture, eye for eye, tooth for tooth; the injury inflicted is the injury to be suffered.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 24, 21, 'One who kills an animal shall make restitution for it; but one who kills a human being shall be put to death.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 24, 22, 'You shall have one law for the alien and for the citizen: for I am the LORD your God.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 24, 23, 'Moses spoke thus to the people of Israel; and they took the blasphemer outside the camp, and stoned him to death. The people of Israel did as the LORD had commanded Moses.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(3, 'Ima', 'Leviticus', 25, 1, 'The LORD spoke to Moses on Mount Sinai, saying:', 'en', 'NRSV-CE', 'The Sabbatical Year'),
(3, 'Ima', 'Leviticus', 25, 2, 'Speak to the people of Israel and say to them: When you enter the land that I am giving you, the land shall observe a sabbath for the LORD.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 25, 3, 'Six years you shall sow your field, and six years you shall prune your vineyard, and gather in their yield;', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 25, 4, 'but in the seventh year there shall be a sabbath of complete rest for the land, a sabbath for the LORD: you shall not sow your field or prune your vineyard.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 25, 5, 'You shall not reap the aftergrowth of your harvest or gather the grapes of your unpruned vine: it shall be a year of complete rest for the land.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 25, 6, 'You may eat what the land yields during its sabbath--you, your male and female slaves, your hired and your bound laborers who live with you;', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 25, 7, 'for your livestock also, and for the wild animals in your land all its yield shall be for food.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 25, 8, 'You shall count off seven weeks of years, seven times seven years, so that the period of seven weeks of years gives forty-nine years.', 'en', 'NRSV-CE', 'The Year of Jubilee'),
(3, 'Ima', 'Leviticus', 25, 9, 'Then you shall have the trumpet sounded loud; on the tenth day of the seventh month--on the day of atonement--you shall have the trumpet sounded throughout all your land.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 25, 10, 'And you shall hallow the fiftieth year and you shall proclaim liberty throughout the land to all its inhabitants. It shall be a jubilee for you: you shall return, every one of you, to your property and every one of you to your family.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 25, 11, 'That fiftieth year shall be a jubilee for you: you shall not sow, or reap the aftergrowth, or harvest the unpruned vines.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 25, 12, 'For it is a jubilee; it shall be holy to you: you shall eat only what the field itself produces.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 25, 13, 'In this year of jubilee you shall return, every one of you, to your property.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 25, 14, 'When you make a sale to your neighbor or buy from your neighbor, you shall not cheat one another.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 25, 15, 'When you buy from your neighbor, you shall pay only for the number of years since the jubilee; the seller shall charge you only for the remaining crop years.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 25, 16, 'If the years are more, you shall increase the price, and if the years are fewer, you shall diminish the price; for it is a certain number of harvests that are being sold to you.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 25, 17, 'You shall not cheat one another, but you shall fear your God; for I am the LORD your God.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 25, 18, 'You shall observe my statutes and faithfully keep my ordinances, so that you may live on the land securely.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 25, 19, 'The land will yield its fruit, and you will eat your fill and live on it securely.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 25, 20, 'Should you ask, "What shall we eat in the seventh year, if we may not sow or gather in our crop?"', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 25, 21, 'I will order my blessing for you in the sixth year, so that it will yield a crop for three years.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 25, 22, 'When you sow in the eighth year, you will be eating from the old crop; until the ninth year, when its produce comes in, you shall eat the old.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 25, 23, 'The land shall not be sold in perpetuity, for the land is mine; with me you are but aliens and tenants.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 25, 24, 'Throughout the land that you hold, you shall provide for the redemption of the land.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 25, 25, 'If anyone of your kin falls into difficulty and sells a piece of property, then the next of kin shall come and redeem what the relative has sold.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 25, 26, 'If the person has no one to redeem it, but then prospers and finds sufficient means to do so,', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 25, 27, 'the years since its sale shall be computed and the difference shall be refunded to the person to whom it was sold, and the property shall be returned.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 25, 28, 'But if there are not sufficient means to recover it, what was sold shall remain with the purchaser until the year of jubilee; in the jubilee it shall be released, and the property shall be returned.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 25, 29, 'If anyone sells a dwelling house in a walled city, it may be redeemed until a year has elapsed since its sale; the right of redemption shall be one year.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 25, 30, 'If it is not redeemed before a full year has elapsed, a house that is in a walled city shall pass in perpetuity to the purchaser, throughout the generations; it shall not be released in the jubilee.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 25, 31, 'But houses in villages that have no walls around them shall be classed as open country; they may be redeemed, and they shall be released in the jubilee.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 25, 32, 'As for the cities of the Levites, the Levites shall forever have the right of redemption of the houses in the cities belonging to them.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 25, 33, 'Such property as may be redeemed from the Levites--houses sold in a city belonging to them--shall be released in the jubilee; because the houses in the cities of the Levites are their possession among the people of Israel.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 25, 34, 'But the open land around their cities may not be sold; for that is their possession for all time.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 25, 35, 'If any of your kin fall into difficulty and become dependent on you, you shall support them; they shall live with you as though resident aliens.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 25, 36, 'Do not take interest in advance or otherwise make a profit from them, but fear your God; let them live with you.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 25, 37, 'You shall not lend them your money at interest taken in advance, or provide them food at a profit.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 25, 38, 'I am the LORD your God, who brought you out of the land of Egypt, to give you the land of Canaan, to be your God.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 25, 39, 'If any who are dependent on you become so impoverished that they sell themselves to you, you shall not make them serve as slaves.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 25, 40, 'They shall remain with you as hired or bound laborers. They shall serve with you until the year of the jubilee.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 25, 41, 'Then they and their children with them shall be free from your authority; they shall go back to their own family and return to their ancestral property.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 25, 42, 'For they are my servants, whom I brought out of the land of Egypt; they shall not be sold as slaves are sold.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 25, 43, 'You shall not rule over them with harshness, but shall fear your God.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 25, 44, 'As for the male and female slaves whom you may have, it is from the nations around you that you may acquire male and female slaves.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 25, 45, 'You may also acquire them from among the aliens residing with you, and from their families that are with you, who have been born in your land; and they may be your property.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 25, 46, 'You may keep them as a possession for your children after you, for them to inherit as property. These you may treat as slaves, but as for your fellow Israelites, no one shall rule over the other with harshness.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 25, 47, 'If resident aliens among you prosper, and if any of your kin fall into difficulty with one of them and sell themselves to an alien, or to a branch of the alien"s family,', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 25, 48, 'after they have sold themselves they shall have the right of redemption; one of their brothers may redeem them,', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 25, 49, 'or their uncle or their uncle"s son may redeem them, or anyone of their family who is of their own flesh may redeem them; or if they prosper they may redeem themselves.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 25, 50, 'They shall compute with the purchaser the total from the year when they sold themselves to the alien until the jubilee year; the price of the sale shall be applied to the number of years: the time they were with the owner shall be rated as the time of a hired laborer.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 25, 51, 'If many years remain, they shall pay for their redemption in proportion to the purchase price;', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 25, 52, 'and if few years remain until the jubilee year, they shall compute thus: according to the years involved they shall make payment for their redemption.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 25, 53, 'As a laborer hired by the year they shall be under the alien"s authority, who shall not, however, rule with harshness over them in your sight.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 25, 54, 'And if they have not been redeemed in any of these ways, they and their children with them shall go free in the jubilee year.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 25, 55, 'For to me the people of Israel are servants; they are my servants whom I brought out from the land of Egypt: I am the LORD your God.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(3, 'Ima', 'Leviticus', 26, 1, 'You shall make for yourselves no idols and erect no carved images or pillars, and you shall not place figured stones in your land, to worship at them; for I am the LORD your God.', 'en', 'NRSV-CE', 'Rewards for Obedience'),
(3, 'Ima', 'Leviticus', 26, 2, 'You shall keep my sabbaths and reverence my sanctuary: I am the LORD.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 26, 3, 'If you follow my statutes and keep my commandments and observe them faithfully,', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 26, 4, 'I will give you your rains in their season, and the land shall yield its produce, and the trees of the field shall yield their fruit.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 26, 5, 'Your threshing shall overtake the vintage, and the vintage shall overtake the sowing; you shall eat your bread to the full, and live securely in your land.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 26, 6, 'And I will grant peace in the land, and you shall lie down, and no one shall make you afraid; I will remove dangerous animals from the land, and no sword shall go through your land.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 26, 7, 'You shall give chase to your enemies, and they shall fall before you by the sword.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 26, 8, 'Five of you shall give chase to a hundred, and a hundred of you shall give chase to ten thousand; your enemies shall fall before you by the sword.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 26, 9, 'I will look with favor upon you and make you fruitful and multiply you; and I will maintain my covenant with you.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 26, 10, 'You shall eat old grain long stored, and you shall have to clear out the old to make way for the new.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 26, 11, 'I will place my dwelling in your midst, and I shall not abhor you.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 26, 12, 'And I will walk among you, and will be your God, and you shall be my people.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 26, 13, 'I am the LORD your God who brought you out of the land of Egypt, to be their slaves no more; I have broken the bars of your yoke and made you walk erect.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 26, 14, 'But if you will not obey me, and do not observe all these commandments,', 'en', 'NRSV-CE', 'Penalties for Disobedience'),
(3, 'Ima', 'Leviticus', 26, 15, 'if you spurn my statutes, and abhor my ordinances, so that you will not observe all my commandments, and you break my covenant,', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 26, 16, 'I in turn will do this to you: I will bring terror on you; consumption and fever that waste the eyes and cause life to pine away. You shall sow your seed in vain, for your enemies shall eat it.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 26, 17, 'I will set my face against you, and you shall be struck down by your enemies; your foes shall rule over you, and you shall flee though no one pursues you.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 26, 18, 'And if in spite of this you will not obey me, I will continue to punish you sevenfold for your sins.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 26, 19, 'I will break your proud glory, and I will make your sky like iron and your earth like copper.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 26, 20, 'Your strength shall be spent to no purpose: your land shall not yield its produce, and the trees of the land shall not yield their fruit.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 26, 21, 'If you continue hostile to me, and will not obey me, I will continue to plague you sevenfold for your sins.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 26, 22, 'I will let loose wild animals against you, and they shall bereave you of your children and destroy your livestock; they shall make you few in number, and your roads shall be deserted.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 26, 23, 'If in spite of these punishments you have not turned back to me, but continue hostile to me,', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 26, 24, 'then I too will continue hostile to you: I myself will strike you sevenfold for your sins.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 26, 25, 'I will bring the sword against you, executing vengeance for the covenant; and if you withdraw within your cities, I will send pestilence among you, and you shall be delivered into enemy hands.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 26, 26, 'When I break your staff of bread, ten women shall bake your bread in a single oven, and they shall dole out your bread by weight; and though you eat, you shall not be satisfied.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 26, 27, 'But if, despite this, you disobey me, and continue hostile to me,', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 26, 28, 'I will continue hostile to you in fury; I in turn will punish you myself sevenfold for your sins.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 26, 29, 'You shall eat the flesh of your sons, and you shall eat the flesh of your daughters.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 26, 30, 'I will destroy your high places and cut down your incense altars; I will heap your carcasses on the carcasses of your idols. I will abhor you.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 26, 31, 'I will lay your cities waste, will make your sanctuaries desolate, and I will not smell your pleasing odors.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 26, 32, 'I will devastate the land, so that your enemies who come to settle in it shall be appalled at it.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 26, 33, 'And you I will scatter among the nations, and I will unsheathe the sword against you; your land shall be a desolation, and your cities a waste.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 26, 34, 'Then the land shall enjoy its sabbath years as long as it lies desolate, while you are in the land of your enemies; then the land shall rest, and enjoy its sabbath years.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 26, 35, 'As long as it lies desolate, it shall have the rest it did not have on your sabbaths when you were living on it.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 26, 36, 'And as for those of you who survive, I will send faintness into their hearts in the lands of their enemies; the sound of a driven leaf shall put them to flight, and they shall flee as one flees from the sword, and they shall fall though no one pursues.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 26, 37, 'They shall stumble over one another, as if to escape a sword, though no one pursues; and you shall have no power to stand against your enemies.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 26, 38, 'You shall perish among the nations, and the land of your enemies shall devour you.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 26, 39, 'And those of you who survive shall languish in the land of your enemies because of their iniquities; also they shall languish because of the iniquities of their ancestors.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 26, 40, 'But if they confess their iniquity and the iniquity of their ancestors, in that they committed treachery against me and, moreover, that they continued hostile to me--', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 26, 41, 'so that I, in turn, continued hostile to them and brought them into the land of their enemies; if then their uncircumcised heart is humbled and they make amends for their iniquity,', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 26, 42, 'then will I remember my covenant with Jacob; I will remember also my covenant with Isaac and also my covenant with Abraham, and I will remember the land.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 26, 43, 'For the land shall be deserted by them, and enjoy its sabbath years by lying desolate without them, while they shall make amends for their iniquity, because they dared to spurn my ordinances, and they abhorred my statutes.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 26, 44, 'Yet for all that, when they are in the land of their enemies, I will not spurn them, or abhor them so as to destroy them utterly and break my covenant with them; for I am the LORD their God;', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 26, 45, 'but I will remember in their favor the covenant with their ancestors whom I brought out of the land of Egypt in the sight of the nations, to be their God: I am the LORD.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 26, 46, 'These are the statutes and ordinances and laws that the LORD established between himself and the people of Israel on Mount Sinai through Moses.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(3, 'Ima', 'Leviticus', 27, 1, 'The LORD spoke to Moses, saying:', 'en', 'NRSV-CE', 'Votive Offerings'),
(3, 'Ima', 'Leviticus', 27, 2, 'Speak to the people of Israel and say to them: When a person makes an explicit vow to the LORD concerning the equivalent for a human being,', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 27, 3, 'the equivalent for a male shall be: from twenty to sixty years of age the equivalent shall be fifty shekels of silver by the sanctuary shekel.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 27, 4, 'If the person is a female, the equivalent is thirty shekels.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 27, 5, 'If the age is from five to twenty years of age, the equivalent is twenty shekels for a male and ten shekels for a female.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 27, 6, 'If the age is from one month to five years, the equivalent for a male is five shekels of silver, and for a female the equivalent is three shekels of silver.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 27, 7, 'And if the person is sixty years old or over, then the equivalent for a male is fifteen shekels, and for a female ten shekels.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 27, 8, 'If any cannot afford the equivalent, they shall be brought before the priest and the priest shall assess them; the priest shall assess them according to what each one making a vow can afford.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 27, 9, 'If it concerns an animal that may be brought as an offering to the LORD, any such that may be given to the LORD shall be holy.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 27, 10, 'Another shall not be exchanged or substituted for it, either good for bad or bad for good; and if one animal is substituted for another, both that one and its substitute shall be holy.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 27, 11, 'If it concerns any unclean animal that may not be brought as an offering to the LORD, the animal shall be presented before the priest.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 27, 12, 'The priest shall assess it: whether good or bad, according to the assessment of the priest, so it shall be.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 27, 13, 'But if it is to be redeemed, one-fifth must be added to the assessment.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 27, 14, 'If a person consecrates a house to the LORD, the priest shall assess it: whether good or bad, as the priest assesses it, so it shall stand.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 27, 15, 'And if the one who consecrates the house wishes to redeem it, one-fifth shall be added to its assessed value, and it shall revert to the original owner.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 27, 16, 'If a person consecrates to the LORD any inherited landholding, its assessment shall be in accordance with its seed requirements: fifty shekels of silver to a homer of barley seed.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 27, 17, 'If the person consecrates the field as of the year of jubilee, that assessment shall stand;', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 27, 18, 'but if the field is consecrated after the jubilee, the priest shall compute the price for it according to the years that remain until the year of jubilee, and the assessment shall be reduced.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 27, 19, 'And if the one who consecrates the field wishes to redeem it, then one-fifth shall be added to its assessed value, and it shall revert to the original owner;', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 27, 20, 'but if the field is not redeemed, or if it has been sold to someone else, it shall no longer be redeemable.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 27, 21, 'But when the field is released in the jubilee, it shall be holy to the LORD as a devoted field; it becomes the priest"s holding.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 27, 22, 'If someone consecrates to the LORD a field that has been purchased, which is not a part of the inherited landholding,', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 27, 23, 'the priest shall compute for it the proportionate assessment up to the year of jubilee, and the assessment shall be paid as of that day, a sacred donation to the LORD.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 27, 24, 'In the year of jubilee the field shall return to the one from whom it was bought, whose holding the land is.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 27, 25, 'All assessments shall be by the sanctuary shekel: twenty gerahs shall make a shekel.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 27, 26, 'A firstling of animals, however, which as a firstling belongs to the LORD, cannot be consecrated by anyone; whether ox or sheep, it is the LORD"s.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 27, 27, 'If it is an unclean animal, it shall be ransomed at its assessment, with one-fifth added; if it is not redeemed, it shall be sold at its assessment.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 27, 28, 'Nothing that a person owns that has been devoted to destruction for the LORD, be it human or animal, or inherited landholding, may be sold or redeemed; every devoted thing is most holy to the LORD.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 27, 29, 'No human beings who have been devoted to destruction can be ransomed; they shall be put to death.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 27, 30, 'All tithes from the land, whether the seed from the ground or the fruit from the tree, are the LORD"s; they are holy to the LORD.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 27, 31, 'If persons wish to redeem any of their tithes, they must add one-fifth to them.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 27, 32, 'All tithes of herd and flock, every tenth one that passes under the shepherd"s staff, shall be holy to the LORD.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 27, 33, 'Let no one inquire whether it is good or bad, or make substitution for it; if one makes substitution for it, then both it and the substitute shall be holy and cannot be redeemed.', 'en', 'NRSV-CE', NULL),
(3, 'Ima', 'Leviticus', 27, 34, 'These are the commandments that the LORD gave to Moses for the people of Israel on Mount Sinai.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(4, 'Bil', 'Numbers', 1, 1, 'The LORD spoke to Moses in the wilderness of Sinai, in the tent of meeting, on the first day of the second month, in the second year after they had come out of the land of Egypt, saying:', 'en', 'NRSV-CE', 'The First Census of Israel'),
(4, 'Bil', 'Numbers', 1, 2, 'Take a census of the whole congregation of Israelites, in their clans, by ancestral houses, according to the number of names, every male individually;', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 1, 3, 'from twenty years old and upward, everyone in Israel able to go to war. You and Aaron shall enroll them, company by company.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 1, 4, 'A man from each tribe shall be with you, each man the head of his ancestral house.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 1, 5, 'These are the names of the men who shall assist you:
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(4, 'Bil', 'Numbers', 2, 1, 'The LORD spoke to Moses and Aaron, saying:', 'en', 'NRSV-CE', 'The Order of Encampment and Marching'),
(4, 'Bil', 'Numbers', 2, 2, 'The Israelites shall camp each in their respective regiments, under ensigns by their ancestral houses; they shall camp facing the tent of meeting on every side.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 2, 3, 'Those to camp on the east side toward the sunrise shall be of the regimental encampment of Judah by companies. The leader of the people of Judah shall be Nahshon son of Amminadab,', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 2, 4, 'with a company as enrolled of seventy-four thousand six hundred.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 2, 5, 'Those to camp next to him shall be the tribe of Issachar. The leader of the Issacharites shall be Nethanel son of Zuar,', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 2, 6, 'with a company as enrolled of fifty-four thousand four hundred.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 2, 7, 'Then the tribe of Zebulun: The leader of the Zebulunites shall be Eliab son of Helon,', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 2, 8, 'with a company as enrolled of fifty-seven thousand four hundred.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 2, 9, 'The total enrollment of the camp of Judah, by companies, is one hundred eighty-six thousand four hundred. They shall set out first on the march.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 2, 10, 'On the south side shall be the regimental encampment of Reuben by companies. The leader of the Reubenites shall be Elizur son of Shedeur,', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 2, 11, 'with a company as enrolled of forty-six thousand five hundred.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 2, 12, 'And those to camp next to him shall be the tribe of Simeon. The leader of the Simeonites shall be Shelumiel son of Zurishaddai,', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 2, 13, 'with a company as enrolled of fifty-nine thousand three hundred.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 2, 14, 'Then the tribe of Gad: The leader of the Gadites shall be Eliasaph son of Reuel,', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 2, 15, 'with a company as enrolled of forty-five thousand six hundred fifty.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 2, 16, 'The total enrollment of the camp of Reuben, by companies, is one hundred fifty-one thousand four hundred fifty. They shall set out second.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 2, 17, 'The tent of meeting, with the camp of the Levites, shall set out in the center of the camps; they shall set out just as they camp, each in position, by their regiments.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 2, 18, 'On the west side shall be the regimental encampment of Ephraim by companies. The leader of the people of Ephraim shall be Elishama son of Ammihud,', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 2, 19, 'with a company as enrolled of forty thousand five hundred.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 2, 20, 'Next to him shall be the tribe of Manasseh. The leader of the people of Manasseh shall be Gamaliel son of Pedahzur,', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 2, 21, 'with a company as enrolled of thirty-two thousand two hundred.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 2, 22, 'Then the tribe of Benjamin: The leader of the Benjaminites shall be Abidan son of Gideoni,', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 2, 23, 'with a company as enrolled of thirty-five thousand four hundred.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 2, 24, 'The total enrollment of the camp of Ephraim, by companies, is one hundred eight thousand one hundred. They shall set out third on the march.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 2, 25, 'On the north side shall be the regimental encampment of Dan by companies. The leader of the Danites shall be Ahiezer son of Ammishaddai,', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 2, 26, 'with a company as enrolled of sixty-two thousand seven hundred.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 2, 27, 'Those to camp next to him shall be the tribe of Asher. The leader of the Asherites shall be Pagiel son of Ochran,', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 2, 28, 'with a company as enrolled of forty-one thousand five hundred.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 2, 29, 'Then the tribe of Naphtali: The leader of the Naphtalites shall be Ahira son of Enan,', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 2, 30, 'with a company as enrolled of fifty-three thousand four hundred.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 2, 31, 'The total enrollment of the camp of Dan is one hundred fifty-seven thousand six hundred. They shall set out last, by companies.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 2, 32, 'This was the enrollment of the Israelites by their ancestral houses; the total enrollment in the camps by their companies was six hundred three thousand five hundred fifty.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 2, 33, 'Just as the LORD had commanded Moses, the Levites were not enrolled among the other Israelites.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 2, 34, 'The Israelites did just as the LORD had commanded Moses: They camped by regiments, and they set out the same way, everyone by clans, according to ancestral houses.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(4, 'Bil', 'Numbers', 3, 1, 'This is the lineage of Aaron and Moses at the time when the LORD spoke with Moses on Mount Sinai.', 'en', 'NRSV-CE', 'The Sons of Aaron'),
(4, 'Bil', 'Numbers', 3, 2, 'These are the names of the sons of Aaron: Nadab the firstborn, and Abihu, Eleazar, and Ithamar;', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 3, 3, 'these are the names of the sons of Aaron, the anointed priests, whom he ordained to minister as priests.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 3, 4, 'Nadab and Abihu died before the LORD when they offered unholy fire before the LORD in the wilderness of Sinai, and they had no children. Eleazar and Ithamar served as priests in the lifetime of their father Aaron.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 3, 5, 'Then the LORD spoke to Moses, saying:', 'en', 'NRSV-CE', 'The Duties of the Levites'),
(4, 'Bil', 'Numbers', 3, 6, 'Bring the tribe of Levi near, and set them before Aaron the priest, so that they may assist him.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 3, 7, 'They shall perform duties for him and for the whole congregation in front of the tent of meeting, doing service at the tabernacle;', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 3, 8, 'they shall be in charge of all the furnishings of the tent of meeting, and attend to the duties for the Israelites as they do service at the tabernacle.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 3, 9, 'You shall give the Levites to Aaron and his descendants; they are unreservedly given to him from among the Israelites.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 3, 10, 'But you shall make a register of Aaron and his descendants; it is they who shall attend to the priesthood, and any outsider who comes near shall be put to death.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 3, 11, 'Then the LORD spoke to Moses, saying:', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 3, 12, 'I hereby accept the Levites from among the Israelites as substitutes for all the firstborn that open the womb among the Israelites. The Levites shall be mine,', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 3, 13, 'for all the firstborn are mine; when I killed all the firstborn in the land of Egypt, I consecrated for my own all the firstborn in Israel, both human and animal; they shall be mine. I am the LORD.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 3, 14, 'Then the LORD spoke to Moses in the wilderness of Sinai, saying:', 'en', 'NRSV-CE', 'A Census of the Levites'),
(4, 'Bil', 'Numbers', 3, 15, 'Enroll the Levites by ancestral houses and by clans. You shall enroll every male from a month old and upward.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 3, 16, 'So Moses enrolled them according to the word of the LORD, as he was commanded.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 3, 17, 'The following were the sons of Levi, by their names: Gershon, Kohath, and Merari.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 3, 18, 'These are the names of the sons of Gershon by their clans: Libni and Shimei.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 3, 19, 'The sons of Kohath by their clans: Amram, Izhar, Hebron, and Uzziel.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 3, 20, 'The sons of Merari by their clans: Mahli and Mushi. These are the clans of the Levites, by their ancestral houses.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 3, 21, 'To Gershon belonged the clan of the Libnites and the clan of the Shimeites; these were the clans of the Gershonites.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 3, 22, 'Their enrollment, counting all the males from a month old and upward, was seven thousand five hundred.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 3, 23, 'The clans of the Gershonites were to camp behind the tabernacle on the west,', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 3, 24, 'with Eliasaph son of Lael as head of the ancestral house of the Gershonites.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 3, 25, 'The responsibility of the sons of Gershon in the tent of meeting was to be the tabernacle, the tent with its covering, the screen for the entrance of the tent of meeting,', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 3, 26, 'the hangings of the court, the screen for the entrance of the court that is around the tabernacle and the altar, and its cords--all the service pertaining to these.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 3, 27, 'To Kohath belonged the clan of the Amramites, the clan of the Izharites, the clan of the Hebronites, and the clan of the Uzzielites; these are the clans of the Kohathites.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 3, 28, 'Counting all the males, from a month old and upward, there were eight thousand six hundred, attending to the duties of the sanctuary.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 3, 29, 'The clans of the Kohathites were to camp on the south side of the tabernacle,', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 3, 30, 'with Elizaphan son of Uzziel as head of the ancestral house of the clans of the Kohathites.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 3, 31, 'Their responsibility was to be the ark, the table, the lampstand, the altars, the vessels of the sanctuary with which the priests minister, and the screen--all the service pertaining to these.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 3, 32, 'Eleazar son of Aaron the priest was to be chief over the leaders of the Levites, and to have oversight of those who had charge of the sanctuary.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 3, 33, 'To Merari belonged the clan of the Mahlites and the clan of the Mushites: these are the clans of Merari.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 3, 34, 'Their enrollment, counting all the males from a month old and upward, was six thousand two hundred.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 3, 35, 'The head of the ancestral house of the clans of Merari was Zuriel son of Abihail; they were to camp on the north side of the tabernacle.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 3, 36, 'The responsibility assigned to the sons of Merari was to be the frames of the tabernacle, the bars, the pillars, the bases, and all their accessories--all the service pertaining to these;', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 3, 37, 'also the pillars of the court all around, with their bases and pegs and cords.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 3, 38, 'Those who were to camp in front of the tabernacle on the east--in front of the tent of meeting toward the east--were Moses and Aaron and Aaron"s sons, having charge of the rites within the sanctuary, whatever had to be done for the Israelites; and any outsider who came near was to be put to death.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 3, 39, 'The total enrollment of the Levites whom Moses and Aaron enrolled at the commandment of the LORD, by their clans, all the males from a month old and upward, was twenty-two thousand.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 3, 40, 'Then the LORD said to Moses: Enroll all the firstborn males of the Israelites, from a month old and upward, and count their names.', 'en', 'NRSV-CE', 'The Redemption of the Firstborn'),
(4, 'Bil', 'Numbers', 3, 41, 'But you shall accept the Levites for me--I am the LORD--as substitutes for all the firstborn among the Israelites, and the livestock of the Levites as substitutes for all the firstborn among the livestock of the Israelites.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 3, 42, 'So Moses enrolled all the firstborn among the Israelites, as the LORD commanded him.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 3, 43, 'The total enrollment, all the firstborn males from a month old and upward, counting the number of names, was twenty-two thousand two hundred seventy-three.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 3, 44, 'Then the LORD spoke to Moses, saying:', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 3, 45, 'Accept the Levites as substitutes for all the firstborn among the Israelites, and the livestock of the Levites as substitutes for their livestock; and the Levites shall be mine. I am the LORD.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 3, 46, 'As the price of redemption of the two hundred seventy-three of the firstborn of the Israelites, over and above the number of the Levites,', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 3, 47, 'you shall accept five shekels apiece, reckoning by the shekel of the sanctuary, a shekel of twenty gerahs.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 3, 48, 'Give to Aaron and his sons the money by which the excess number of them is redeemed.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 3, 49, 'So Moses took the redemption money from those who were over and above those redeemed by the Levites;', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 3, 50, 'from the firstborn of the Israelites he took the money, one thousand three hundred sixty-five shekels, reckoned by the shekel of the sanctuary;', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 3, 51, 'and Moses gave the redemption money to Aaron and his sons, according to the word of the LORD, as the LORD had commanded Moses.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(4, 'Bil', 'Numbers', 4, 1, 'The LORD spoke to Moses and Aaron, saying:', 'en', 'NRSV-CE', 'The Kohathites'),
(4, 'Bil', 'Numbers', 4, 2, 'Take a census of the Kohathites separate from the other Levites, by their clans and their ancestral houses,', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 4, 3, 'from thirty years old up to fifty years old, all who qualify to do work relating to the tent of meeting.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 4, 4, 'The service of the Kohathites relating to the tent of meeting concerns the most holy things.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 4, 5, 'When the camp is to set out, Aaron and his sons shall go in and take down the screening curtain, and cover the ark of the covenant with it;', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 4, 6, 'then they shall put on it a covering of fine leather, and spread over that a cloth all of blue, and shall put its poles in place.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 4, 7, 'Over the table of the bread of the Presence they shall spread a blue cloth, and put on it the plates, the dishes for incense, the bowls, and the flagons for the drink offering; the regular bread also shall be on it;', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 4, 8, 'then they shall spread over them a crimson cloth, and cover it with a covering of fine leather, and shall put its poles in place.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 4, 9, 'They shall take a blue cloth, and cover the lampstand for the light, with its lamps, its snuffers, its trays, and all the vessels for oil with which it is supplied;', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 4, 10, 'and they shall put it with all its utensils in a covering of fine leather, and put it on the carrying frame.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 4, 11, 'Over the golden altar they shall spread a blue cloth, and cover it with a covering of fine leather, and shall put its poles in place;', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 4, 12, 'and they shall take all the utensils of the service that are used in the sanctuary, and put them in a blue cloth, and cover them with a covering of fine leather, and put them on the carrying frame.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 4, 13, 'They shall take away the ashes from the altar, and spread a purple cloth over it;', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 4, 14, 'and they shall put on it all the utensils of the altar, which are used for the service there, the firepans, the forks, the shovels, and the basins, all the utensils of the altar; and they shall spread on it a covering of fine leather, and shall put its poles in place.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 4, 15, 'When Aaron and his sons have finished covering the sanctuary and all the furnishings of the sanctuary, as the camp sets out, after that the Kohathites shall come to carry these, but they must not touch the holy things, or they will die. These are the things of the tent of meeting that the Kohathites are to carry.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 4, 16, 'Eleazar son of Aaron the priest shall have charge of the oil for the light, the fragrant incense, the regular grain offering, and the anointing oil, the oversight of all the tabernacle and all that is in it, in the sanctuary and in its utensils.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 4, 17, 'Then the LORD spoke to Moses and Aaron, saying:', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 4, 18, 'You must not let the tribe of the clans of the Kohathites be destroyed from among the Levites.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 4, 19, 'This is how you must deal with them in order that they may live and not die when they come near to the most holy things: Aaron and his sons shall go in and assign each to a particular task or burden.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 4, 20, 'But the Kohathites must not go in to look on the holy things even for a moment; otherwise they will die.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 4, 21, 'Then the LORD spoke to Moses, saying:', 'en', 'NRSV-CE', 'The Gershonites and Merarites'),
(4, 'Bil', 'Numbers', 4, 22, 'Take a census of the Gershonites also, by their ancestral houses and by their clans;', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 4, 23, 'from thirty years old up to fifty years old you shall enroll them, all who qualify to do work in the tent of meeting.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 4, 24, 'This is the service of the clans of the Gershonites, in serving and bearing burdens:', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 4, 25, 'They shall carry the curtains of the tabernacle, and the tent of meeting with its covering, and the outer covering of fine leather that is on top of it, and the screen for the entrance of the tent of meeting,', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 4, 26, 'and the hangings of the court, and the screen for the entrance of the gate of the court that is around the tabernacle and the altar, and their cords, and all the equipment for their service; and they shall do all that needs to be done with regard to them.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 4, 27, 'All the service of the Gershonites shall be at the command of Aaron and his sons, in all that they are to carry, and in all that they have to do; and you shall assign to their charge all that they are to carry.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 4, 28, 'This is the service of the clans of the Gershonites relating to the tent of meeting, and their responsibilities are to be under the oversight of Ithamar son of Aaron the priest.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 4, 29, 'As for the Merarites, you shall enroll them by their clans and their ancestral houses;', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 4, 30, 'from thirty years old up to fifty years old you shall enroll them, everyone who qualifies to do the work of the tent of meeting.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 4, 31, 'This is what they are charged to carry, as the whole of their service in the tent of meeting: the frames of the tabernacle, with its bars, pillars, and bases,', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 4, 32, 'and the pillars of the court all around with their bases, pegs, and cords, with all their equipment and all their related service; and you shall assign by name the objects that they are required to carry.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 4, 33, 'This is the service of the clans of the Merarites, the whole of their service relating to the tent of meeting, under the hand of Ithamar son of Aaron the priest.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 4, 34, 'So Moses and Aaron and the leaders of the congregation enrolled the Kohathites, by their clans and their ancestral houses,', 'en', 'NRSV-CE', 'Census of the Levites'),
(4, 'Bil', 'Numbers', 4, 35, 'from thirty years old up to fifty years old, everyone who qualified for work relating to the tent of meeting;', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 4, 36, 'and their enrollment by clans was two thousand seven hundred fifty.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 4, 37, 'This was the enrollment of the clans of the Kohathites, all who served at the tent of meeting, whom Moses and Aaron enrolled according to the commandment of the LORD by Moses.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 4, 38, 'The enrollment of the Gershonites, by their clans and their ancestral houses,', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 4, 39, 'from thirty years old up to fifty years old, everyone who qualified for work relating to the tent of meeting--', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 4, 40, 'their enrollment by their clans and their ancestral houses was two thousand six hundred thirty.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 4, 41, 'This was the enrollment of the clans of the Gershonites, all who served at the tent of meeting, whom Moses and Aaron enrolled according to the commandment of the LORD.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 4, 42, 'The enrollment of the clans of the Merarites, by their clans and their ancestral houses,', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 4, 43, 'from thirty years old up to fifty years old, everyone who qualified for work relating to the tent of meeting--', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 4, 44, 'their enrollment by their clans was three thousand two hundred.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 4, 45, 'This is the enrollment of the clans of the Merarites, whom Moses and Aaron enrolled according to the commandment of the LORD by Moses.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 4, 46, 'All those who were enrolled of the Levites, whom Moses and Aaron and the leaders of Israel enrolled, by their clans and their ancestral houses,', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 4, 47, 'from thirty years old up to fifty years old, everyone who qualified to do the work of service and the work of bearing burdens relating to the tent of meeting,', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 4, 48, 'their enrollment was eight thousand five hundred eighty.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 4, 49, 'According to the commandment of the LORD through Moses they were appointed to their several tasks of serving or carrying; thus they were enrolled by him, as the LORD commanded Moses.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(4, 'Bil', 'Numbers', 5, 1, 'The LORD spoke to Moses, saying:', 'en', 'NRSV-CE', 'Unclean Persons'),
(4, 'Bil', 'Numbers', 5, 2, 'Command the Israelites to put out of the camp everyone who is leprous, or has a discharge, and everyone who is unclean through contact with a corpse;', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 5, 3, 'you shall put out both male and female, putting them outside the camp; they must not defile their camp, where I dwell among them.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 5, 4, 'The Israelites did so, putting them outside the camp; as the LORD had spoken to Moses, so the Israelites did.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 5, 5, 'The LORD spoke to Moses, saying:', 'en', 'NRSV-CE', 'Confession and Restitution'),
(4, 'Bil', 'Numbers', 5, 6, 'Speak to the Israelites: When a man or a woman wrongs another, breaking faith with the LORD, that person incurs guilt', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 5, 7, 'and shall confess the sin that has been committed. The person shall make full restitution for the wrong, adding one-fifth to it, and giving it to the one who was wronged.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 5, 8, 'If the injured party has no next of kin to whom restitution may be made for the wrong, the restitution for wrong shall go to the LORD for the priest, in addition to the ram of atonement with which atonement is made for the guilty party.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 5, 9, 'Among all the sacred donations of the Israelites, every gift that they bring to the priest shall be his.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 5, 10, 'The sacred donations of all are their own; whatever anyone gives to the priest shall be his.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 5, 11, 'The LORD spoke to Moses, saying:', 'en', 'NRSV-CE', 'Concerning an Unfaithful Wife'),
(4, 'Bil', 'Numbers', 5, 12, 'Speak to the Israelites and say to them: If any man"s wife goes astray and is unfaithful to him,', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 5, 13, 'if a man has had intercourse with her but it is hidden from her husband, so that she is undetected though she has defiled herself, and there is no witness against her since she was not caught in the act;', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 5, 14, 'if a spirit of jealousy comes on him, and he is jealous of his wife who has defiled herself; or if a spirit of jealousy comes on him, and he is jealous of his wife, though she has not defiled herself;', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 5, 15, 'then the man shall bring his wife to the priest. And he shall bring the offering required for her, one-tenth of an ephah of barley flour. He shall pour no oil on it and put no frankincense on it, for it is a grain offering of jealousy, a grain offering of remembrance, bringing iniquity to remembrance.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 5, 16, 'Then the priest shall bring her near, and set her before the LORD;', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 5, 17, 'the priest shall take holy water in an earthen vessel, and take some of the dust that is on the floor of the tabernacle and put it into the water.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 5, 18, 'The priest shall set the woman before the LORD, dishevel the woman"s hair, and place in her hands the grain offering of remembrance, which is the grain offering of jealousy. In his own hand the priest shall have the water of bitterness that brings the curse.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 5, 19, 'Then the priest shall make her take an oath, saying, "If no man has lain with you, if you have not turned aside to uncleanness while under your husband"s authority, be immune to this water of bitterness that brings the curse.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 5, 20, 'But if you have gone astray while under your husband"s authority, if you have defiled yourself and some man other than your husband has had intercourse with you,"', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 5, 21, '--let the priest make the woman take the oath of the curse and say to the woman--"the LORD make you an execration and an oath among your people, when the LORD makes your uterus drop, your womb discharge;', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 5, 22, 'now may this water that brings the curse enter your bowels and make your womb discharge, your uterus drop!" And the woman shall say, "Amen. Amen."', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 5, 23, 'Then the priest shall put these curses in writing, and wash them off into the water of bitterness.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 5, 24, 'He shall make the woman drink the water of bitterness that brings the curse, and the water that brings the curse shall enter her and cause bitter pain.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 5, 25, 'The priest shall take the grain offering of jealousy out of the woman"s hand, and shall elevate the grain offering before the LORD and bring it to the altar;', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 5, 26, 'and the priest shall take a handful of the grain offering, as its memorial portion, and turn it into smoke on the altar, and afterward shall make the woman drink the water.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 5, 27, 'When he has made her drink the water, then, if she has defiled herself and has been unfaithful to her husband, the water that brings the curse shall enter into her and cause bitter pain, and her womb shall discharge, her uterus drop, and the woman shall become an execration among her people.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 5, 28, 'But if the woman has not defiled herself and is clean, then she shall be immune and be able to conceive children.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 5, 29, 'This is the law in cases of jealousy, when a wife, while under her husband"s authority, goes astray and defiles herself,', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 5, 30, 'or when a spirit of jealousy comes on a man and he is jealous of his wife; then he shall set the woman before the LORD, and the priest shall apply this entire law to her.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 5, 31, 'The man shall be free from iniquity, but the woman shall bear her iniquity.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(4, 'Bil', 'Numbers', 6, 1, 'The LORD spoke to Moses, saying:', 'en', 'NRSV-CE', 'The Nazirites'),
(4, 'Bil', 'Numbers', 6, 2, 'Speak to the Israelites and say to them: When either men or women make a special vow, the vow of a nazirite, to separate themselves to the LORD,', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 6, 3, 'they shall separate themselves from wine and strong drink; they shall drink no wine vinegar or other vinegar, and shall not drink any grape juice or eat grapes, fresh or dried.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 6, 4, 'All their days as nazirites they shall eat nothing that is produced by the grapevine, not even the seeds or the skins.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 6, 5, 'All the days of their nazirite vow no razor shall come upon the head; until the time is completed for which they separate themselves to the LORD, they shall be holy; they shall let the locks of the head grow long.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 6, 6, 'All the days that they separate themselves to the LORD they shall not go near a corpse.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 6, 7, 'Even if their father or mother, brother or sister, should die, they may not defile themselves; because their consecration to God is upon the head.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 6, 8, 'All their days as nazirites they are holy to the LORD.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 6, 9, 'If someone dies very suddenly nearby, defiling the consecrated head, then they shall shave the head on the day of their cleansing; on the seventh day they shall shave it.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 6, 10, 'On the eighth day they shall bring two turtledoves or two young pigeons to the priest at the entrance of the tent of meeting,', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 6, 11, 'and the priest shall offer one as a sin offering and the other as a burnt offering, and make atonement for them, because they incurred guilt by reason of the corpse. They shall sanctify the head that same day,', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 6, 12, 'and separate themselves to the LORD for their days as nazirites, and bring a male lamb a year old as a guilt offering. The former time shall be void, because the consecrated head was defiled.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 6, 13, 'This is the law for the nazirites when the time of their consecration has been completed: they shall be brought to the entrance of the tent of meeting,', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 6, 14, 'and they shall offer their gift to the LORD, one male lamb a year old without blemish as a burnt offering, one ewe lamb a year old without blemish as a sin offering, one ram without blemish as an offering of well-being,', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 6, 15, 'and a basket of unleavened bread, cakes of choice flour mixed with oil and unleavened wafers spread with oil, with their grain offering and their drink offerings.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 6, 16, 'The priest shall present them before the LORD and offer their sin offering and burnt offering,', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 6, 17, 'and shall offer the ram as a sacrifice of well-being to the LORD, with the basket of unleavened bread; the priest also shall make the accompanying grain offering and drink offering.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 6, 18, 'Then the nazirites shall shave the consecrated head at the entrance of the tent of meeting, and shall take the hair from the consecrated head and put it on the fire under the sacrifice of well-being.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 6, 19, 'The priest shall take the shoulder of the ram, when it is boiled, and one unleavened cake out of the basket, and one unleavened wafer, and shall put them in the palms of the nazirites, after they have shaved the consecrated head.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 6, 20, 'Then the priest shall elevate them as an elevation offering before the LORD; they are a holy portion for the priest, together with the breast that is elevated and the thigh that is offered. After that the nazirites may drink wine.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 6, 21, 'This is the law for the nazirites who take a vow. Their offering to the LORD must be in accordance with the nazirite vow, apart from what else they can afford. In accordance with whatever vow they take, so they shall do, following the law for their consecration.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 6, 22, 'The LORD spoke to Moses, saying:', 'en', 'NRSV-CE', 'The Priestly Benediction'),
(4, 'Bil', 'Numbers', 6, 23, 'Speak to Aaron and his sons, saying, Thus you shall bless the Israelites: You shall say to them,', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 6, 24, 'The LORD bless you and keep you;', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 6, 25, 'the LORD make his face to shine upon you, and be gracious to you;', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 6, 26, 'the LORD lift up his countenance upon you, and give you peace.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 6, 27, 'So they shall put my name on the Israelites, and I will bless them.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(4, 'Bil', 'Numbers', 7, 1, 'On the day when Moses had finished setting up the tabernacle, and had anointed and consecrated it with all its furnishings, and had anointed and consecrated the altar with all its utensils,', 'en', 'NRSV-CE', 'Offerings of the Leaders'),
(4, 'Bil', 'Numbers', 7, 2, 'the leaders of Israel, heads of their ancestral houses, the leaders of the tribes, who were over those who were enrolled, made offerings.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 7, 3, 'They brought their offerings before the LORD, six covered wagons and twelve oxen, a wagon for every two of the leaders, and for each one an ox; they presented them before the tabernacle.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 7, 4, 'Then the LORD said to Moses:', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 7, 5, 'Accept these from them, that they may be used in doing the service of the tent of meeting, and give them to the Levites, to each according to his service.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 7, 6, 'So Moses took the wagons and the oxen, and gave them to the Levites.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 7, 7, 'Two wagons and four oxen he gave to the Gershonites, according to their service;', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 7, 8, 'and four wagons and eight oxen he gave to the Merarites, according to their service, under the direction of Ithamar son of Aaron the priest.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 7, 9, 'But to the Kohathites he gave none, because they were charged with the care of the holy things that had to be carried on the shoulders.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 7, 10, 'The leaders also presented offerings for the dedication of the altar at the time when it was anointed; the leaders presented their offering before the altar.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 7, 11, 'The LORD said to Moses: They shall present their offerings, one leader each day, for the dedication of the altar.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 7, 12, 'The one who presented his offering the first day was Nahshon son of Amminadab, of the tribe of Judah;', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 7, 13, 'his offering was one silver plate weighing one hundred thirty shekels, one silver basin weighing seventy shekels, according to the shekel of the sanctuary, both of them full of choice flour mixed with oil for a grain offering;', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 7, 14, 'one golden dish weighing ten shekels, full of incense;', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 7, 15, 'one young bull, one ram, one male lamb a year old, for a burnt offering;', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 7, 16, 'one male goat for a sin offering;', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 7, 17, 'and for the sacrifice of well-being, two oxen, five rams, five male goats, and five male lambs a year old. This was the offering of Nahshon son of Amminadab.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 7, 18, 'On the second day Nethanel son of Zuar, the leader of Issachar, presented an offering;', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 7, 19, 'he presented for his offering one silver plate weighing one hundred thirty shekels, one silver basin weighing seventy shekels, according to the shekel of the sanctuary, both of them full of choice flour mixed with oil for a grain offering;', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 7, 20, 'one golden dish weighing ten shekels, full of incense;', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 7, 21, 'one young bull, one ram, one male lamb a year old, as a burnt offering;', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 7, 22, 'one male goat as a sin offering;', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 7, 23, 'and for the sacrifice of well-being, two oxen, five rams, five male goats, and five male lambs a year old. This was the offering of Nethanel son of Zuar.', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 7, 24, 'On the third day Eliab son of Helon, the leader of the Zebulunites:', 'en', 'NRSV-CE', NULL),
