(4, 'Bil', 'Numbers', 7, 66, 'On the tenth day Ahiezer son of Ammishaddai, the leader of the Danites:', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 7, 67, 'his offering was one silver plate weighing one hundred thirty shekels, one silver basin weighing seventy shekels, according to the shekel of the sanctuary, both of them full of choice flour mixed with oil for a grain offering;', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 7, 68, 'one golden dish weighing ten shekels, full of incense;', 'en', 'NRSV-CE', NULL),
