(4, 'Bil', 'Numbers', 7, 72, 'On the eleventh day Pagiel son of Ochran, the leader of the Asherites:', 'en', 'NRSV-CE', NULL),
(4, 'Bil', 'Numbers', 7, 73, 'his offering was one silver plate weighing one hundred thirty shekels, one silver basin weighing seventy shekels, according to the shekel of the sanctuary, both of them full of choice flour mixed with oil for a grain offering;', 'en', 'NRSV-CE', NULL),
